export interface AnalysisQueueMessage {
  repoId: string
  checkpointId: string
  queuedAt: string
}

export function isAnalysisQueueMessage(msg: unknown): msg is AnalysisQueueMessage {
  return (
    typeof msg === "object" &&
    msg !== null &&
    "repoId" in msg &&
    "checkpointId" in msg &&
    "queuedAt" in msg &&
    typeof (msg as AnalysisQueueMessage).repoId === "string" &&
    typeof (msg as AnalysisQueueMessage).checkpointId === "string" &&
    typeof (msg as AnalysisQueueMessage).queuedAt === "string" &&
    !("checkpointIds" in msg)
  )
}

function log(event: string, data: Record<string, unknown>): void {
  console.log(`[analysis-queue] ${event}`, JSON.stringify(data))
}

const MAX_ANALYSIS_RETRIES = 3
const CHECKPOINT_ANALYSIS_TIMEOUT_MS = 10 * 60_000

// Errors where retrying won't help because the input is missing or malformed.
// Matched by substring against the error message.
//
// "Checkpoint not found in database" and "No transcript data available" used
// to live here, but both are prerequisite-race signals: a sibling writer
// (the other webhook, or GitSource reconciliation) fills the missing half shortly
// after and will re-call dispatchAnalysis. Letting the existing 60s → 300s
// backoff retry them recovers the race without the noisy permanent log.
//
// The DB-inconsistency case (hydrator stamped complete without writing
// transcript_stripped) is *also* permanent, but it's surfaced as the
// dedicated TranscriptMissingAfterHydrationError class below and matched by
// instanceof — string-only fallback would silently flip permanent →
// transient if anyone reworded the message.
const PERMANENT_ERROR_PATTERNS = ["No transcript chunks available for analysis"] as const

// DB inconsistency: payload_hydration_state=complete but transcript_stripped
// is missing or empty. Won't self-resolve, so retries just delay the loud
// signal that a human needs to look at it. Kept as a class (not a string
// pattern) so isPermanentAnalysisError matches by instanceof — rewording the
// message can't silently flip it transient.
export class TranscriptMissingAfterHydrationError extends Error {
  constructor() {
    super("Transcript missing despite hydration_state=complete")
    this.name = "TranscriptMissingAfterHydrationError"
  }
}

export function isPermanentAnalysisError(error: unknown): boolean {
  if (error instanceof TranscriptMissingAfterHydrationError) return true
  const message = errorString(error)
  return PERMANENT_ERROR_PATTERNS.some((pattern) => message.includes(pattern))
}

// Thrown when the hydrator has confirmed a checkpoint has no sessions to
// analyze (`payload_hydration_state = 'complete_empty'`). The queue handler
// treats this as a clean skip — ack the message, no retry, no error log.
export class CheckpointHasNoSessionsError extends Error {
  constructor() {
    super("Checkpoint has no sessions to analyze")
    this.name = "CheckpointHasNoSessionsError"
  }
}

interface DbLoadedTranscript {
  sessions: SessionTranscript[]
  sessionMetadata: StrippedSessionMetadata[]
  payloadHydrationState: CheckpointPayloadHydrationState
}

// DB-only transcript loader for the analysis worker. Unlike
// loadCheckpointTranscript (used by the frontend transcript routes), this
// does not fall back to fetching from GitHub — a missing transcript means
// the worker should branch on payload_hydration_state and either retry,
// skip, or surface a DB inconsistency, not pay the round-trip per attempt.
async function loadCheckpointTranscriptFromDbOnly(
  db: Db,
  repoId: string,
  checkpointId: string,
  checkpoint: CheckpointWithCommit,
  env?: Env,
): Promise<DbLoadedTranscript> {
  const transcriptRow = await db.checkpoints.getTranscript(repoId, checkpointId)
  const payloadHydrationState = transcriptRow?.payload_hydration_state ?? "pending"
  const dbSessionsRaw = transcriptRow?.sessions ?? null

  // PS-first (legacy data lives in transcript_stripped), R2 otherwise.
  // R2 read failures throw so we can distinguish a real outage from "no
  // content exists" — the analysis worker treats both as "transcript not
  // available" (state machine handles retry/skip), but only the throw path
  // is logged so a transient R2 outage shows up in observability.
  let transcriptStripped: string | null
  try {
    transcriptStripped = await readCheckpointTranscript(
      env?.TRANSCRIPT_BUCKET,
      repoId,
      checkpointId,
      extractSessionIds(checkpoint.sessions),
      transcriptRow?.transcript_stripped ?? null,
    )
  } catch (err) {
    console.warn(`[analysis-queue] R2 read failed for ${repoId}/${checkpointId}:`, errorString(err))
    transcriptStripped = null
  }

  if (!transcriptStripped) {
    return { sessions: [], sessionMetadata: [], payloadHydrationState }
  }

  const sessionsMap = parseStoredTranscriptSessions(transcriptStripped)
  if (!sessionsMap) {
    return { sessions: [], sessionMetadata: [], payloadHydrationState }
  }

  // DB-or-synthesize cascade for session metadata. Skip the GitHub branch
  // present in resolveSessionMetadata — if the hydrator wrote transcript
  // bytes but no metadata, default-synthesized metadata is good enough for
  // the analyzer (agent name + session index), and we avoid a network call
  // on every analysis attempt.
  const fromDb = buildSessionMetadataFromDb(dbSessionsRaw)
  const sessionMetadata =
    fromDb.length > 0 ? fromDb : synthesizeDefaultMetadata(sessionsMap, LEGACY_FALLBACK_AGENT_NAME)

  const sessions = buildSessionsFromStrippedTranscript(
    sessionsMap,
    sessionMetadata,
    checkpoint.storage_version,
  )

  return { sessions, sessionMetadata, payloadHydrationState }
}

function getAnthropicRateLimiterStub(env: Env): AnthropicRateLimiterStub | undefined {
  const ns = env.ANTHROPIC_RATE_LIMITER
  if (!ns) return undefined
  return ns.get(ns.idFromName("global"))
}

function retryDelaySeconds(attempts: number): number {
  // 1st retry after 60s, 2nd after 300s (5 min). Gives transient upstream
  // failures room to clear without hammering the API.
  if (attempts <= 1) return 60
  return 300
}

