export interface ParsedSessionForMetrics {
  agent: string
  messages: TranscriptMessage[]
}

export function extractToolMetricsFromSessions(sessions: ParsedSessionForMetrics[]): {
  skillsUsed: string[]
  mcpServersUsed: { name: string; count: number }[]
  toolProfile: ToolProfile | null
} {
  const skills = new Set<string>()
  const mcpCounts = new Map<string, number>()
  const counts: Record<ToolMixCategoryKey, number> = {
    shell: 0,
    fileOps: 0,
    search: 0,
    mcp: 0,
    agent: 0,
    other: 0,
  }
  let total = 0

  for (const session of sessions) {
    const parser = getParserForAgent(session.agent)
    for (const message of session.messages) {
      for (const call of message.toolCalls ?? []) {
        total++
        const cat = parser.classifyTool?.(call) ?? "other"
        counts[cat]++

        const skill = parser.extractSkillFromTool?.(call)
        if (skill) skills.add(skill)

        const mcpServer = parser.extractMcpServerFromTool?.(call)
        if (mcpServer) {
          mcpCounts.set(mcpServer, (mcpCounts.get(mcpServer) ?? 0) + 1)
        }
      }
    }
  }

  let toolProfile: ToolProfile | null = null
  if (total > 0) {
    const categories = Object.fromEntries(
      TOOL_MIX_CATEGORY_KEYS.map((k) => [k, { count: counts[k] }]),
    ) as Record<ToolMixCategoryKey, { count: number }>
    toolProfile = { categories, total }
  }

  return {
    skillsUsed: Array.from(skills),
    mcpServersUsed: Array.from(mcpCounts.entries())
      .map(([name, count]) => ({ name, count }))
      .sort((a, b) => b.count - a.count),
    toolProfile,
  }
}

export async function generateAndStoreReview(
  env: Env,
  db: Db,
  repoId: string,
  checkpointId: string,
  queuedAt: string,
  options: { maxChunkTokens?: number } = {},
): Promise<StoredCheckpointAnalysis> {
  const anthropicApiKey = env.ANTHROPIC_API_KEY_ANALYSIS
  if (!anthropicApiKey) {
    throw new Error("ANTHROPIC_API_KEY_ANALYSIS is not configured")
  }

  const checkpointLocation = await db.checkpoints.findById(repoId, checkpointId)
  if (!checkpointLocation?.commit) {
    throw new Error("Checkpoint not found in database")
  }
  const checkpointCommit = checkpointLocation.commit

  // DB-only transcript read. The hydrator (webhook + admin retry paths)
  // writes transcript_stripped before analysis is dispatched, so an empty
  // result here means hydration hasn't landed yet, was definitively empty,
  // or failed — branch on payload_hydration_state below.
  const loaded = await loadCheckpointTranscriptFromDbOnly(
    db,
    repoId,
    checkpointId,
    checkpointCommit,
    env,
  )

  if (loaded.sessions.length === 0) {
    switch (loaded.payloadHydrationState) {
      case "complete_empty":
        // Hydrator confirmed there are no sessions to analyze. Clean skip —
        // the catch handler acks without an error log.
        throw new CheckpointHasNoSessionsError()
      case "complete":
        // Hydration says complete, but transcript_stripped is missing or
        // empty. Real DB inconsistency — surface loudly so it gets noticed.
        throw new TranscriptMissingAfterHydrationError()
      case "error":
      case "pending":
      default:
        // Race with the hydrator (most common) or a known transient hydration
        // failure. Retry; the queue handler suppresses message_error until
        // the final attempt for transient errors. The state suffix lets the
        // dashboard slice retries by which branch fired (pending=race vs
        // error=hydrator failure).
        throw new Error(
          `No transcript data available (payload_hydration_state=${loaded.payloadHydrationState})`,
        )
    }
  }

  log("transcript_loaded", {
    repoId,
    checkpointId,
    sessionCount: loaded.sessions.length,
  })

  const rateLimiter = getAnthropicRateLimiterStub(env)
  const attemptId: AttemptId = { repoId, checkpointId, queuedAt }
  const review = await runAttemptWithTimeout(
    db,
    attemptId,
    (signal) =>
      generateCheckpointAnalysis(anthropicApiKey, loaded.sessions, checkpointCommit, {
        ...(options.maxChunkTokens ? { maxChunkTokens: options.maxChunkTokens } : {}),
        ...(rateLimiter ? { rateLimiter } : {}),
        signal,
      }),
    { timeoutMs: CHECKPOINT_ANALYSIS_TIMEOUT_MS },
  )

  const fullReview = decorateReviewWithMetrics(review, loaded)

  const completed = await completeAttempt(db, attemptId, JSON.stringify(fullReview))
  if (!completed) {
    log("skip_superseded_reindex", { repoId, checkpointId, queuedAt })
    return fullReview
  }

  // Denormalize qualitative facets out of the analysis blob into side tables
  // so /me/recap can aggregate via SQL GROUP BY instead of fetching + parsing
  // JSON. Idempotent inside upsertFacets (DELETE-then-INSERT in a tx), so
  // safe under worker retries. Counts collapse repeated entries:
  // ["bug_fix", "bug_fix"] -> {name: "bug_fix", count: 2}.
  const labelCounts = (fullReview.extraction?.labels ?? []).reduce<Map<string, number>>((m, l) => {
    m.set(l, (m.get(l) ?? 0) + 1)
    return m
  }, new Map())
  const skillCounts = (fullReview.skillsUsed ?? []).reduce<Map<string, number>>((m, s) => {
    m.set(s, (m.get(s) ?? 0) + 1)
    return m
  }, new Map())
  const toolMixFacets: Array<{ name: string; count: number }> = []
  if (fullReview.toolProfile?.categories) {
    for (const [name, v] of Object.entries(fullReview.toolProfile.categories)) {
      const count = (v as { count?: number } | null)?.count ?? 0
      if (count > 0) toolMixFacets.push({ name, count })
    }
  }
  // mcpServersUsed is already collapsed to {name, count} by extractToolMetrics
  // (above) — no further reduce needed. Filter zero/negative counts so the
  // facet table never carries dead rows.
  const mcpServersFacets: Array<{ name: string; count: number }> = (fullReview.mcpServersUsed ?? [])
    .filter((m) => (m.count ?? 0) > 0)
    .map((m) => ({ name: m.name, count: m.count ?? 0 }))

  await db.analyses.upsertFacets(
    repoId,
    checkpointId,
    Array.from(labelCounts, ([name, count]) => ({ name, count })),
    Array.from(skillCounts, ([name, count]) => ({ name, count })),
    toolMixFacets,
    mcpServersFacets,
  )

  // transcript_tokens / files_changed are scalars on the analyses row itself.
  // Persisting alongside upsertFacets keeps the worker's "post-markComplete
  // denormalization" step in one place. Idempotent — same UPDATE under
  // retries yields the same final state.
  await db.analyses.updateScalarAggregates(
    repoId,
    checkpointId,
    fullReview.total_transcript_tokens ?? 0,
    fullReview.totalFilesChanged ?? 0,
  )

  await reindexWithAnalysis(env, repoId, checkpointCommit, fullReview)
  return fullReview
}

