import type { TranscriptMessage, ToolCall, ToolMixCategoryKey } from "../../types"

/**
 * Transcript file format:
 * - "jsonl": One JSON object per line (Claude Code, Cursor, Copilot CLI)
 * - "json": Single JSON object with a messages array (OpenCode, Gemini CLI)
 */
export type TranscriptFormat = "jsonl" | "json"

/**
 * Result of parsing a transcript, including metadata about parse quality.
 */
export interface TranscriptParseResult {
  messages: TranscriptMessage[]
  /** True when the parser is a best-effort fallback, not a native parser for this agent */
  isFallback: boolean
  /** Warning message when parsing may be incomplete */
  warning?: string
}

/**
 * Interface that every agent transcript parser must implement.
 */
export interface TranscriptParser {
  /** Human-readable name for this parser */
  readonly name: string
  /** Transcript file format this parser expects */
  readonly format: TranscriptFormat
  /** Parse raw transcript content into transcript messages */
  parse(content: string): TranscriptParseResult
  /**
   * Slice raw transcript content before stripping and storage.
   * Parsers with non-standard checkpoint offsets can override the shared
   * JSONL/JSON slicing behavior.
   * Returns undefined to use the shared format-based storage slicing.
   */
  sliceForStorage?(content: string, offset: number): string | undefined
  /**
   * Strip transcript content down to only what parse() needs.
   * For JSONL formats, the shared stripTranscript handles this.
   * JSON-format parsers should implement this to drop large fields
   * (diffs, summaries, etc.) that the parser doesn't read.
   * Returns the stripped content string. Default: return as-is.
   */
  strip?(content: string): string
  /**
   * Parse transcript content starting from the given offset.
   * For JSONL parsers: offset = line number to start from.
   * For JSON parsers: offset = message index to start from.
   * Returns only messages from the offset onward.
   */
  parseFrom?(content: string, offset: number): TranscriptParseResult
  /**
   * Classify a tool call into the shared toolMix bucket. Optional —
   * undefined means "I don't know how to classify this agent's tools";
   * callers default to "other" via the optional-chaining fallback.
   */
  classifyTool?(call: ToolCall): ToolMixCategoryKey
  /**
   * Extract a skill name from a tool call, when applicable. Returns null
   * when the call doesn't represent a skill invocation. Claude implements
   * via the `Skill` tool; other agents return null until they grow the
   * same surface.
   */
  extractSkillFromTool?(call: ToolCall): string | null
  /**
   * Extract an MCP server name from a tool call, when applicable. Returns
   * null when the call isn't an MCP invocation. Claude parses the
   * `mcp__server__tool` prefix convention; other agents return null
   * until their parsers surface MCP server names.
   */
  extractMcpServerFromTool?(call: ToolCall): string | null
}

/**
 * Shared parseFrom for JSONL-based parsers (Claude Code, Cursor).
 * Slices lines at the given offset, then delegates to the parser's parse().
 */
export function jsonlParseFrom(
  parser: TranscriptParser,
  content: string,
  offset: number,
): TranscriptParseResult {
  if (offset <= 0) return parser.parse(content)
  const tail = content.split("\n").slice(offset).join("\n")
  return parser.parse(tail)
}

export function jsonlSliceForStorage(content: string, offset: number): string {
  const tail = content.split("\n").slice(offset)
  // If the offset overruns the file (e.g. transcript was truncated upstream),
  // fall back to the original content so the commit/checkpoint page still
  // renders something instead of an empty session. `every` covers the
  // trailing-newline case where split leaves a single "" past the data.
  if (tail.every((line) => line === "")) return content
  return tail.join("\n")
}

import type {
  TranscriptMessage,
  ToolCall,
  ToolCallResult,
  TranscriptRuntimeTag,
  ToolMixCategoryKey,
} from "../../types"
import { extractRuntimeTags, extractToolUseBlocks } from "./common"
import type { TranscriptParser, TranscriptParseResult } from "./types"
import { jsonlParseFrom } from "./types"

// Extract text and image content from message content (string or array of blocks)
interface ExtractedContent {
  text: string
  images: Array<{ mediaType: string; data: string }>
  hasToolResults: boolean
}

// Pattern for image references that Claude Code outputs when it "reads" an image.
// These are text markers like "[Image: source: /path/to/file.png]" - not actual image data.
// We strip these since the actual images are rendered from base64 content blocks.
const IMAGE_REFERENCE_PATTERN = /\[Image: source: [^\]]+\]/g

function extractTextContent(content: unknown): ExtractedContent {
  if (typeof content === "string") {
    return {
      text: content.replace(IMAGE_REFERENCE_PATTERN, "").trim(),
      images: [],
      hasToolResults: false,
    }
  }
  if (!Array.isArray(content)) {
    return { text: "", images: [], hasToolResults: false }
  }

  let text = ""
  const images: Array<{ mediaType: string; data: string }> = []
  let hasToolResults = false

  for (const block of content) {
    if (typeof block === "object" && block !== null) {
      const b = block as Record<string, unknown>
      if (b.type === "text") {
        text += (b.text as string) || ""
      } else if (b.type === "tool_result") {
        hasToolResults = true
      } else if (b.type === "image") {
        const source = b.source as Record<string, unknown> | undefined
        if (source?.type === "base64" && source.data && source.media_type) {
          images.push({
            mediaType: source.media_type as string,
            data: source.data as string,
          })
        }
      }
    }
  }
  // Strip image reference markers from text (see comment above)
  text = text.replace(IMAGE_REFERENCE_PATTERN, "").trim()

  return { text, images, hasToolResults }
}

// Extract tool_result metadata from a tool result record
function extractToolResultMetadata(parsed: Record<string, unknown>): ToolCallResult | undefined {
  const toolUseResult = parsed.toolUseResult as Record<string, unknown> | undefined
  if (!toolUseResult) return undefined

  const result: ToolCallResult = {
    type: (toolUseResult.type as "text" | "error") || "text",
  }

  // For file reads
  const file = toolUseResult.file as Record<string, unknown> | undefined
  if (file) {
    result.file = {
      filePath: file.filePath as string,
      numLines: file.numLines as number | undefined,
    }
  }

  // For errors
  if (toolUseResult.error) {
    result.error = toolUseResult.error as string
    result.type = "error"
  }

  // For AskUserQuestion - extract user's answers
  const answers = toolUseResult.answers as Record<string, string> | undefined
  if (answers) {
    result.answers = answers
  }

  return result
}

/**
 * Parse Claude Code JSONL transcript into TranscriptMessage[].
 * Returns a natural conversation: user prompt -> final assistant reply (before next user prompt).
 * Also extracts tool calls made during each assistant turn.
 */
function parseClaudeCodeTranscript(jsonlContent: string): TranscriptMessage[] {
  const lines = jsonlContent.split("\n").filter((line) => line.trim())

  // Internal types for collecting data
  type InternalMessage = {
    role: "user" | "assistant"
    content: string
    images: Array<{ mediaType: string; data: string }>
    timestamp: string
    id: string
    runtimeTags?: TranscriptRuntimeTag[]
    directToolCalls?: ToolCall[]
  }

  // Collect all tool_use records: id -> { name, input, timestamp }
  type ToolUseData = Omit<ToolCall, "id" | "result">
  const toolUseById = new Map<string, ToolUseData>()

  // Collect all tool_result records: tool_use_id -> result metadata
  const toolResultById = new Map<string, ToolCallResult>()

  // First pass: collect tool_use and tool_result records
  for (const line of lines) {
    let parsed: Record<string, unknown>
    try {
      parsed = JSON.parse(line)
    } catch {
      continue
    }

    const type = parsed.type as string | undefined
    const message = parsed.message as Record<string, unknown> | undefined
    const timestamp = (parsed.timestamp as string) || new Date().toISOString()

    if (type === "assistant" && message?.content) {
      // Check for tool_use blocks in assistant messages
      const toolUses = extractToolUseBlocks(message.content)
      for (const tu of toolUses) {
        toolUseById.set(tu.id, {
          name: tu.name,
          input: tu.input,
          timestamp,
        })
      }
    } else if (type === "user" && message?.content) {
      // Check for tool_result blocks (they come as "user" type messages)
      const content = message.content as unknown[]
      if (Array.isArray(content)) {
        for (const block of content) {
          if (typeof block === "object" && block !== null) {
            const b = block as Record<string, unknown>
            if (b.type === "tool_result" && b.tool_use_id) {
              const resultMeta = extractToolResultMetadata(parsed)
              if (resultMeta) {
                toolResultById.set(b.tool_use_id as string, resultMeta)
              }
            }
          }
        }
      }
    }
  }

  // Second pass: collect messages and track tool calls per turn
  const messages: InternalMessage[] = []
  const assistantByRequestId = new Map<string, number>()

  // Track tool calls in the current turn (between user messages)
  // Key is the index in messages array where we'll eventually attach them
  const toolCallsPerTurn: ToolCall[] = []

  for (const line of lines) {
    let parsed: Record<string, unknown>
    try {
      parsed = JSON.parse(line)
    } catch {
      continue
    }

    const type = parsed.type as string | undefined
    if (type !== "user" && type !== "assistant") continue

    const message = parsed.message as Record<string, unknown> | undefined
    if (!message) continue

    const timestamp = (parsed.timestamp as string) || new Date().toISOString()

    if (type === "assistant") {
      // Check for tool_use blocks first
      const toolUses = extractToolUseBlocks(message.content)
      const directToolCalls: ToolCall[] = []
      for (const tu of toolUses) {
        const toolData = toolUseById.get(tu.id)
        if (toolData) {
          const toolCall: ToolCall = {
            id: tu.id,
            name: tu.name,
            input: tu.input,
            timestamp: toolData.timestamp,
            result: toolResultById.get(tu.id),
          }
          toolCallsPerTurn.push(toolCall)
          directToolCalls.push(toolCall)
        }
      }

      // Also extract text content for the message
      const { text, images } = extractTextContent(message.content)
      const { content, runtimeTags } = stripInternalTags(text)
      const requestId = (parsed.requestId as string) || (message.id as string)
      if (!requestId) continue

      const existingIdx = assistantByRequestId.get(requestId)
      if (existingIdx !== undefined) {
        // Streaming update: replace with latest content
        if (content) {
          messages[existingIdx].content = content
        }
        if (runtimeTags.length > 0) {
          messages[existingIdx].runtimeTags = runtimeTags
        }
        if (images.length > 0) {
          messages[existingIdx].images = images
        }
        if (directToolCalls.length > 0) {
          const existingDirectToolCalls = messages[existingIdx].directToolCalls ?? []
          messages[existingIdx].directToolCalls = [
            ...existingDirectToolCalls,
            ...directToolCalls.filter(
              (call) => !existingDirectToolCalls.some((existing) => existing.id === call.id),
            ),
          ]
        }
        // Always advance timestamp so tool calls from later streaming
        // lines (e.g. tool_use arriving after text) fall within the
        // turn's time range for getToolCallsInRange.
        messages[existingIdx].timestamp = timestamp
      } else {
        assistantByRequestId.set(requestId, messages.length)
        messages.push({
          role: "assistant",
          content,
          images,
          timestamp,
          id: (message.id as string) || crypto.randomUUID(),
          runtimeTags: runtimeTags.length > 0 ? runtimeTags : undefined,
          directToolCalls: directToolCalls.length > 0 ? directToolCalls : undefined,
        })
      }
    } else {
      // User message
      const { text, images, hasToolResults } = extractTextContent(message.content)
      const { content, runtimeTags } = stripInternalTags(text)

      // Skip user messages that are only tool results and have no text/images
      if ((!content && images.length === 0 && runtimeTags.length === 0) || hasToolResults) continue

      messages.push({
        role: "user",
        content,
        images,
        timestamp,
        id: (parsed.uuid as string) || crypto.randomUUID(),
        runtimeTags: runtimeTags.length > 0 ? runtimeTags : undefined,
      })
    }
  }

  // Sort by timestamp
  messages.sort((a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime())

  // Sort tool calls by timestamp for proper ordering
  toolCallsPerTurn.sort((a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime())

  // Build result: keep ALL assistant messages with content between user messages.
  // Claude Code can emit multiple assistant responses (text → tool calls → summary)
  // before the user responds — each is a separate API call with its own requestId.
  // Attach tool calls to the assistant message they follow (by timestamp range).
  const result: TranscriptMessage[] = []
  // Collect all assistants with content between user messages
  let pendingAssistants: InternalMessage[] = []
  let lastUserTimestamp: string | null = null

  // Keep tool-only assistant turns so their tool_use blocks do not get
  // re-attributed to the next text-bearing assistant turn.
  const hasContent = (m: InternalMessage) =>
    m.content ||
    m.images.length > 0 ||
    m.runtimeTags?.length ||
    (m.directToolCalls?.length ?? 0) > 0

  // Helper to get tool calls between two timestamps
  const getToolCallsInRange = (startTs: string | null, endTs: string): ToolCall[] => {
    const endTime = new Date(endTs).getTime()
    const startTime = startTs !== null ? new Date(startTs).getTime() : null
    return toolCallsPerTurn.filter((tc) => {
      const tcTime = new Date(tc.timestamp).getTime()
      if (startTime === null) {
        return tcTime <= endTime
      }
      return tcTime > startTime && tcTime <= endTime
    })
  }

  const mergeToolCalls = (rangeCalls: ToolCall[], directCalls: ToolCall[]): ToolCall[] => {
    const byId = new Map<string, ToolCall>()
    for (const call of rangeCalls) byId.set(call.id, call)
    for (const call of directCalls) byId.set(call.id, call)
    return Array.from(byId.values()).sort(
      (a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime(),
    )
  }

  const flushAssistants = () => {
    for (let i = 0; i < pendingAssistants.length; i++) {
      const assistant = pendingAssistants[i]
      // Tool calls range: from previous assistant's timestamp (or last user) to this assistant's timestamp
      const rangeStart = i === 0 ? lastUserTimestamp : pendingAssistants[i - 1].timestamp
      const { directToolCalls, ...assistantMessage } = assistant
      const turnToolCalls = mergeToolCalls(
        getToolCallsInRange(rangeStart, assistant.timestamp),
        directToolCalls ?? [],
      )
      result.push({
        ...assistantMessage,
        images: assistantMessage.images.length > 0 ? assistantMessage.images : undefined,
        toolCalls: turnToolCalls,
      })
    }
    pendingAssistants = []
  }

  for (const msg of messages) {
    if (msg.role === "user") {
      flushAssistants()
      result.push({
        ...msg,
        images: msg.images.length > 0 ? msg.images : undefined,
      })
      lastUserTimestamp = msg.timestamp
    } else if (hasContent(msg)) {
      pendingAssistants.push(msg)
    }
  }

  // Handle any remaining assistant messages after the last user message
  flushAssistants()

  return result
}

/** Strip system-injected tags from Claude Code message content. */
function stripInternalTags(content: string): {
  content: string
  runtimeTags: TranscriptRuntimeTag[]
} {
  const stripped = extractRuntimeTags(content)
  return {
    content: stripped.content.trim(),
    runtimeTags: stripped.runtimeTags,
  }
}

/**
 * Parser for Claude Code JSONL transcripts.
 */
export class ClaudeCodeParser implements TranscriptParser {
  readonly name = "Claude Code"
  readonly format = "jsonl" as const

  parse(jsonlContent: string): TranscriptParseResult {
    const messages = parseClaudeCodeTranscript(jsonlContent).filter(
      (msg) =>
        msg.content || msg.images?.length || msg.toolCalls?.length || msg.runtimeTags?.length,
    )

    return {
      messages,
      isFallback: false,
    }
  }

  parseFrom(content: string, offset: number): TranscriptParseResult {
    return jsonlParseFrom(this, content, offset)
  }

  classifyTool(call: ToolCall): ToolMixCategoryKey {
    const name = call.name
    if (name === "Bash") return "shell"
    if (name === "Read" || name === "Write" || name === "Edit") return "fileOps"
    if (name === "Grep" || name === "Glob") return "search"
    if (name === "Skill" || name === "Agent") return "agent"
    if (name.startsWith("mcp__")) return "mcp"
    return "other"
  }

  extractSkillFromTool(call: ToolCall): string | null {
    if (call.name !== "Skill") return null
    const skill = (call.input as Record<string, unknown>)?.skill
    return typeof skill === "string" && skill.length > 0 ? skill : null
  }

  extractMcpServerFromTool(call: ToolCall): string | null {
    if (!call.name.startsWith("mcp__")) return null
    const segments = call.name.split("__")
    return segments.length >= 3 && segments[1] ? segments[1] : null
  }
}

import type { ToolMixCategoryKey, TranscriptMessage, ToolCall, ToolCallResult } from "../../types"
import { extractRuntimeTags, isSyntheticInputText } from "./common"
import type { TranscriptParser, TranscriptParseResult } from "./types"
import { jsonlParseFrom } from "./types"
import { UnifiedTranscriptParser, isUnifiedTranscript } from "./unified-transcript-parser"

interface CodexRolloutLine {
  timestamp?: string
  type?: string
  payload?: Record<string, unknown>
}

interface CodexContentItem {
  type?: string
  text?: string
}

const unifiedTranscriptParser = new UnifiedTranscriptParser()

function extractCodexMcpServer(payload: Record<string, unknown>): string | undefined {
  const namespace = payload.namespace
  if (typeof namespace === "string" && namespace.startsWith("mcp__")) {
    const parts = namespace.split("__")
    if (parts[1]) return parts[1]
  }

  const invocation = payload.invocation
  if (typeof invocation === "object" && invocation !== null) {
    const server = (invocation as Record<string, unknown>).server
    if (typeof server === "string" && server.trim()) return server
  }

  return undefined
}

function parseJSONL(content: string): CodexRolloutLine[] {
  return content
    .split("\n")
    .map((line) => line.trim())
    .filter(Boolean)
    .flatMap((line) => {
      try {
        return [JSON.parse(line) as CodexRolloutLine]
      } catch {
        return []
      }
    })
}

function extractMessageText(
  content: unknown,
  role: "user" | "assistant",
  filterSyntheticPreamble: boolean,
): string {
  if (!Array.isArray(content)) return ""

  return content
    .flatMap((item) => {
      if (typeof item !== "object" || item === null) return []
      const parsed = item as CodexContentItem
      if (!parsed.text?.trim()) return []
      if (role === "user" && parsed.type && parsed.type !== "input_text") return []
      if (role === "assistant" && parsed.type && parsed.type !== "output_text") return []
      if (filterSyntheticPreamble && isSyntheticInputText(parsed.text)) return []
      return [parsed.text]
    })
    .join("\n")
    .trim()
}

function parseToolInput(
  payloadType: string,
  toolName: string,
  payload: Record<string, unknown>,
): Record<string, unknown> {
  const rawInput =
    payload.input ??
    payload.arguments ??
    payload.args ??
    payload.command ??
    payload.text ??
    payload.content

  if (rawInput && typeof rawInput === "object" && !Array.isArray(rawInput)) {
    return rawInput as Record<string, unknown>
  }

  if (typeof rawInput !== "string" || !rawInput.trim()) {
    return {}
  }

  if (toolName === "apply_patch") return { patch: rawInput }
  if (payloadType === "local_shell_call") return { command: rawInput }
  return { input: rawInput }
}

function parseToolResult(output: unknown, status: unknown): ToolCallResult | undefined {
  const resultType = status === "error" ? "error" : "text"

  if (typeof output === "string") {
    const trimmed = output.trim()
    if (!trimmed) return undefined
    return {
      type: resultType,
      output: trimmed,
      error: resultType === "error" ? trimmed : undefined,
    }
  }

  if (typeof output !== "object" || output === null) {
    return status === "error" ? { type: "error", error: "Tool call failed" } : undefined
  }

  const parsed = output as Record<string, unknown>
  const text =
    typeof parsed.text === "string"
      ? parsed.text
      : typeof parsed.output === "string"
        ? parsed.output
        : typeof parsed.stderr === "string"
          ? parsed.stderr
          : typeof parsed.stdout === "string"
            ? parsed.stdout
            : null

  if (text?.trim()) {
    return {
      type: resultType,
      output: text.trim(),
      error: resultType === "error" ? text.trim() : undefined,
    }
  }

  if (status === "error") {
    return {
      type: "error",
      error: typeof parsed.error === "string" ? parsed.error : "Tool call failed",
    }
  }

  return undefined
}

function parseCodexRollout(content: string): TranscriptMessage[] {
  const lines = parseJSONL(content)
  const messages: TranscriptMessage[] = []
  const toolCallsById = new Map<string, ToolCall>()
  let pendingAssistantText: string[] = []
  let pendingToolCalls: ToolCall[] = []
  let pendingAssistantTimestamp: string | null = null
  let pendingAssistantId: string | null = null
  // Synthetic-wrapper filtering only applies until the first real user prompt
  // has been emitted. After that, the codex runtime doesn't inject preambles,
  // so later user turns are passed through verbatim — a user pasting
  // "<environment_context>..." or "# AGENTS.md instructions for ..." to
  // discuss it must not be silently dropped.
  let hasEmittedUserMessage = false

  const flushAssistant = () => {
    if (pendingAssistantText.length === 0 && pendingToolCalls.length === 0) {
      pendingAssistantTimestamp = null
      pendingAssistantId = null
      return
    }

    const stripped = extractRuntimeTags(pendingAssistantText.join("\n\n").trim())
    messages.push({
      id: pendingAssistantId ?? crypto.randomUUID(),
      role: "assistant",
      content: stripped.content.trim(),
      timestamp: pendingAssistantTimestamp ?? new Date().toISOString(),
      toolCalls: pendingToolCalls.length > 0 ? [...pendingToolCalls] : undefined,
      runtimeTags: stripped.runtimeTags.length > 0 ? stripped.runtimeTags : undefined,
    })

    pendingAssistantText = []
    pendingToolCalls = []
    pendingAssistantTimestamp = null
    pendingAssistantId = null
    toolCallsById.clear()
  }

  for (const line of lines) {
    if (!line.payload) continue

    const payload = line.payload
    const payloadType = typeof payload.type === "string" ? payload.type : ""
    const timestamp = line.timestamp ?? new Date().toISOString()

    if (line.type === "event_msg" && payloadType === "mcp_tool_call_end") {
      const toolId = (payload.call_id as string) ?? (payload.id as string)
      if (!toolId) continue

      const toolCall = toolCallsById.get(toolId)
      if (!toolCall) continue

      const mcpServer = extractCodexMcpServer(payload)
      if (mcpServer) {
        toolCall.metadata = { ...toolCall.metadata, mcpServer }
      }
      continue
    }

    if (line.type !== "response_item") continue

    if (payloadType === "message") {
      const role =
        payload.role === "assistant" ? "assistant" : payload.role === "user" ? "user" : null
      if (!role) continue

      const text = extractMessageText(
        payload.content,
        role,
        role === "user" && !hasEmittedUserMessage,
      )

      if (role === "user") {
        flushAssistant()
        const stripped = extractRuntimeTags(text)
        if (!stripped.content.trim() && stripped.runtimeTags.length === 0) continue
        messages.push({
          id: (payload.id as string) ?? crypto.randomUUID(),
          role: "user",
          content: stripped.content.trim(),
          timestamp,
          runtimeTags: stripped.runtimeTags.length > 0 ? stripped.runtimeTags : undefined,
        })
        hasEmittedUserMessage = true
        continue
      }

      if (!pendingAssistantTimestamp) pendingAssistantTimestamp = timestamp
      pendingAssistantId = (payload.id as string) ?? pendingAssistantId ?? crypto.randomUUID()
      if (text) pendingAssistantText.push(text)
      continue
    }

    if (
      payloadType === "custom_tool_call" ||
      payloadType === "function_call" ||
      payloadType === "local_shell_call"
    ) {
      if (!pendingAssistantTimestamp) pendingAssistantTimestamp = timestamp
      pendingAssistantId = pendingAssistantId ?? crypto.randomUUID()

      const toolName =
        typeof payload.name === "string"
          ? payload.name
          : payloadType === "local_shell_call"
            ? "shell"
            : payloadType
      const toolId =
        (payload.call_id as string) ??
        (payload.id as string) ??
        `${toolName}-${timestamp}-${pendingToolCalls.length}`

      const toolCall: ToolCall = {
        id: toolId,
        name: toolName,
        input: parseToolInput(payloadType, toolName, payload),
        timestamp,
      }
      const mcpServer = extractCodexMcpServer(payload)
      if (mcpServer) {
        toolCall.metadata = { mcpServer }
      }

      pendingToolCalls.push(toolCall)
      toolCallsById.set(toolId, toolCall)
      continue
    }

    if (
      payloadType === "custom_tool_call_output" ||
      payloadType === "function_call_output" ||
      payloadType === "local_shell_call_output"
    ) {
      const toolId = (payload.call_id as string) ?? (payload.id as string)
      if (!toolId) continue

      const toolCall = toolCallsById.get(toolId)
      if (!toolCall) continue

      const result = parseToolResult(payload.output, payload.status)
      if (result) {
        toolCall.result = result
      }
    }
  }

  flushAssistant()
  return messages
}

/**
 * Parser for Codex transcripts.
 * Supports both legacy rollout JSONL and the new unified transcript.jsonl format.
 */
export class CodexParser implements TranscriptParser {
  readonly name = "Codex"
  readonly format = "jsonl" as const

  parse(content: string): TranscriptParseResult {
    if (isUnifiedTranscript(content)) {
      return unifiedTranscriptParser.parse(content)
    }

    return {
      messages: parseCodexRollout(content),
      isFallback: false,
    }
  }

  parseFrom(content: string, offset: number): TranscriptParseResult {
    if (isUnifiedTranscript(content)) {
      return unifiedTranscriptParser.parseFrom(content, offset)
    }

    return jsonlParseFrom(this, content, offset)
  }

  strip(content: string): string {
    if (isUnifiedTranscript(content)) {
      return unifiedTranscriptParser.strip(content)
    }

    return parseJSONL(content)
      .filter(
        (line) =>
          line.type === "response_item" ||
          (line.type === "event_msg" && line.payload?.type === "mcp_tool_call_end"),
      )
      .map((line) => {
        const payload = line.payload ?? {}
        const payloadType = typeof payload.type === "string" ? payload.type : undefined
        return JSON.stringify({
          timestamp: line.timestamp,
          type: line.type,
          payload: {
            type: payloadType,
            role: payload.role,
            id: payload.id,
            call_id: payload.call_id,
            name: payload.name,
            namespace: payload.namespace,
            invocation: payload.invocation,
            status: payload.status,
            input: payload.input,
            arguments: payload.arguments,
            args: payload.args,
            command: payload.command,
            text: payload.text,
            content: payload.content,
            output: payload.output,
          },
        })
      })
      .join("\n")
  }

  classifyTool(call: ToolCall): ToolMixCategoryKey {
    const name = call.name
    if (
      name === "exec_command" ||
      name === "local_shell_call" ||
      name === "write_stdin" ||
      name === "bash" ||
      name === "shell"
    ) {
      return "shell"
    }
    if (
      name === "apply_patch" ||
      name === "read_file" ||
      name === "write_file" ||
      name === "edit"
    ) {
      return "fileOps"
    }
    if (name === "update_plan") return "other"
    // Heuristic: Codex's MCP host emits underscore-prefixed tool names in
    // production (e.g. _fetch_pr_comments, _list_pull_request_review_threads).
    // Codex's native tools today never start with `_` — revisit this branch
    // if upstream introduces a native tool with an underscore prefix.
    if (name.startsWith("_")) return "mcp"
    return "other"
  }

  extractSkillFromTool(_call: ToolCall): string | null {
    return null // Codex has no Skill-tool equivalent
  }

  extractMcpServerFromTool(call: ToolCall): string | null {
    return call.metadata?.mcpServer ?? null
  }
}

import type { TranscriptMessage, ToolCall, ToolMixCategoryKey } from "../../types"
import type { TranscriptParser, TranscriptParseResult } from "./types"

interface GeminiMessage {
  id?: string
  type?: string
  content?: string
  timestamp?: string
  toolCalls?: Array<{
    id: string
    name: string
    args?: Record<string, unknown>
    status?: string
  }>
}

interface GeminiLog {
  messages?: GeminiMessage[]
}

function parseGeminiLog(content: string): GeminiLog | null {
  try {
    const log: GeminiLog = JSON.parse(content)
    if (!Array.isArray(log.messages)) return null
    return log
  } catch {
    return null
  }
}

function parseGeminiMessages(rawMessages: GeminiMessage[]): TranscriptMessage[] {
  const result: TranscriptMessage[] = []
  const now = new Date().toISOString()

  for (const msg of rawMessages) {
    if (msg.type !== "user" && msg.type !== "gemini") continue
    if (!msg.content && (!msg.toolCalls || msg.toolCalls.length === 0)) continue

    const content = (msg.content ?? "").trim()

    const ts = msg.timestamp || now
    const role: "user" | "assistant" = msg.type === "user" ? "user" : "assistant"

    const toolCalls: ToolCall[] | undefined =
      role === "assistant" && msg.toolCalls && msg.toolCalls.length > 0
        ? msg.toolCalls.map((tc) => ({
            id: tc.id,
            name: tc.name,
            input: (tc.args ?? {}) as Record<string, unknown>,
            timestamp: ts,
          }))
        : undefined

    result.push({
      id: msg.id || crypto.randomUUID(),
      role,
      content,
      timestamp: ts,
      toolCalls,
    })
  }

  return result
}

/**
 * Parser for Gemini CLI transcripts (single JSON with messages array).
 */
export class GeminiParser implements TranscriptParser {
  readonly name = "Gemini CLI"
  readonly format = "json" as const

  parse(jsonContent: string): TranscriptParseResult {
    const log = parseGeminiLog(jsonContent)
    if (!log) return { messages: [], isFallback: false }

    return {
      messages: parseGeminiMessages(log.messages!),
      isFallback: false,
    }
  }

  parseFrom(content: string, offset: number): TranscriptParseResult {
    if (offset <= 0) return this.parse(content)

    const log = parseGeminiLog(content)
    if (!log) return { messages: [], isFallback: false }

    // Slice raw messages BEFORE filtering, matching CLI's countTranscriptItems
    const slicedMessages = log.messages!.slice(offset)

    return {
      messages: parseGeminiMessages(slicedMessages),
      isFallback: false,
    }
  }

  /** Strip to only the fields parse() reads: messages[].{id, type, content, timestamp, toolCalls} */
  strip(content: string): string {
    let log: Record<string, unknown>
    try {
      log = JSON.parse(content)
    } catch {
      return content
    }

    const stripped: Record<string, unknown> = {
      messages: Array.isArray(log.messages)
        ? (log.messages as Array<Record<string, unknown>>).map((msg) => ({
            id: msg.id,
            type: msg.type,
            content: msg.content,
            timestamp: msg.timestamp,
            toolCalls: msg.toolCalls,
          }))
        : [],
    }

    return JSON.stringify(stripped)
  }

  classifyTool(call: ToolCall): ToolMixCategoryKey {
    const name = call.name
    if (name === "run_shell_command") return "shell"
    if (name === "read_file" || name === "write_file" || name === "replace") return "fileOps"
    if (name === "glob" || name === "search_file_content" || name === "list_directory") {
      return "search"
    }
    return "other"
  }

  extractSkillFromTool(_call: ToolCall): string | null {
    return null
  }

  extractMcpServerFromTool(_call: ToolCall): string | null {
    return null
  }
}

import type { TranscriptMessage, ToolCall, ToolCallResult } from "../../types"
import type { TranscriptParser, TranscriptParseResult } from "./types"
import { jsonlParseFrom } from "./types"

/**
 * Pi transcript format (JSONL):
 *
 * - `{"type":"session", ...}`       — session metadata (ignored)
 * - `{"type":"model_change", ...}`  — model switch  (ignored)
 * - `{"type":"message", "message":{"role":"user"|"assistant"|"toolResult", ...}}`
 *
 * Assistant content blocks:
 *   - `{type:"text", text:"..."}` — text output
 *   - `{type:"toolCall", id, name, arguments}` — tool invocation
 *   - `{type:"thinking", ...}` — thinking (stripped)
 *
 * Tool results arrive as separate `role:"toolResult"` lines with `toolCallId`.
 */

interface PiLine {
  type: string
  id?: string
  timestamp?: string
  message?: PiMessage
}

interface PiMessage {
  role: string
  content?: unknown[]
  toolCallId?: string
  toolName?: string
  isError?: boolean
  timestamp?: number
}

interface PiContentBlock {
  type?: string
  text?: string
  thinking?: string
  id?: string
  name?: string
  arguments?: Record<string, unknown>
}

function parseLines(content: string): PiLine[] {
  return content
    .split("\n")
    .filter((l) => l.trim())
    .flatMap((line) => {
      try {
        return [JSON.parse(line) as PiLine]
      } catch {
        return []
      }
    })
}

function extractText(content: unknown[]): string {
  return (content as PiContentBlock[])
    .filter((b) => b.type === "text" && b.text)
    .map((b) => b.text!)
    .join("\n")
    .trim()
}

function extractToolCalls(content: unknown[], timestamp: string): ToolCall[] {
  return (content as PiContentBlock[])
    .filter((b) => b.type === "toolCall" && b.name)
    .map((b) => ({
      id: b.id ?? crypto.randomUUID(),
      name: b.name!,
      input: b.arguments ?? {},
      timestamp,
    }))
}

function parsePiTranscript(content: string): TranscriptMessage[] {
  const lines = parseLines(content)

  // Pass 1: collect tool results by toolCallId
  const toolResultById = new Map<string, ToolCallResult>()
  for (const line of lines) {
    if (line.type !== "message" || line.message?.role !== "toolResult") continue
    const msg = line.message
    if (!msg.toolCallId) continue

    const text = Array.isArray(msg.content) ? extractText(msg.content) : ""
    toolResultById.set(msg.toolCallId, {
      type: msg.isError ? "error" : "text",
      output: text,
      error: msg.isError ? text || "Tool call failed" : undefined,
    })
  }

  // Pass 2: build messages, merging consecutive assistant turns
  const messages: TranscriptMessage[] = []
  let pendingText: string[] = []
  let pendingToolCalls: ToolCall[] = []
  let pendingTimestamp: string | null = null
  let pendingId: string | null = null

  const flushAssistant = () => {
    if (pendingText.length === 0 && pendingToolCalls.length === 0) {
      pendingTimestamp = null
      pendingId = null
      return
    }

    // Attach results to tool calls
    for (const tc of pendingToolCalls) {
      const result = toolResultById.get(tc.id)
      if (result) tc.result = result
    }

    messages.push({
      id: pendingId ?? crypto.randomUUID(),
      role: "assistant",
      content: pendingText.join("\n\n").trim(),
      timestamp: pendingTimestamp ?? new Date().toISOString(),
      toolCalls: pendingToolCalls.length > 0 ? [...pendingToolCalls] : undefined,
    })

    pendingText = []
    pendingToolCalls = []
    pendingTimestamp = null
    pendingId = null
  }

  for (const line of lines) {
    if (line.type !== "message" || !line.message) continue
    const msg = line.message
    const timestamp = line.timestamp ?? new Date().toISOString()

    if (msg.role === "user") {
      flushAssistant()
      const text = Array.isArray(msg.content) ? extractText(msg.content) : ""
      if (!text) continue
      messages.push({
        id: line.id ?? crypto.randomUUID(),
        role: "user",
        content: text,
        timestamp,
      })
    } else if (msg.role === "assistant") {
      if (!pendingTimestamp) pendingTimestamp = timestamp
      if (!pendingId) pendingId = line.id ?? crypto.randomUUID()

      if (Array.isArray(msg.content)) {
        const text = extractText(msg.content)
        if (text) pendingText.push(text)
        pendingToolCalls.push(...extractToolCalls(msg.content, timestamp))
      }
    }
    // toolResult lines are handled in pass 1
  }

  flushAssistant()
  return messages
}

/**
 * Parser for Pi transcripts.
 */
export class PiParser implements TranscriptParser {
  readonly name = "Pi"
  readonly format = "jsonl" as const

  parse(content: string): TranscriptParseResult {
    return {
      messages: parsePiTranscript(content),
      isFallback: false,
    }
  }

  parseFrom(content: string, offset: number): TranscriptParseResult {
    return jsonlParseFrom(this, content, offset)
  }

  strip(content: string): string {
    return parseLines(content)
      .filter((line) => line.type === "message")
      .map((line) => {
        const msg = line.message
        if (!msg) return JSON.stringify(line)

        // Strip thinking blocks, usage, and other metadata from assistant messages
        const strippedContent = Array.isArray(msg.content)
          ? (msg.content as PiContentBlock[])
              .filter((b) => b.type !== "thinking")
              .map((b) => {
                if (b.type === "toolCall") {
                  return { type: b.type, id: b.id, name: b.name, arguments: b.arguments }
                }
                return { type: b.type, text: b.text }
              })
          : msg.content

        return JSON.stringify({
          type: line.type,
          id: line.id,
          timestamp: line.timestamp,
          message: {
            role: msg.role,
            content: strippedContent,
            toolCallId: msg.toolCallId,
            toolName: msg.toolName,
            isError: msg.isError,
          },
        })
      })
      .join("\n")
  }
}

import type { TranscriptMessage, ToolCall, ToolCallResult } from "../../types"
import { isSyntheticInputText } from "./common"
import type { TranscriptParser } from "./types"
import { jsonlParseFrom } from "./types"

// Claude Code emits textual image markers alongside the actual base64 image blocks.
// Strip those markers so the UI only renders the real image payload.
const IMAGE_REFERENCE_PATTERN = /\[Image: source: [^\]]+\]/g

interface TranscriptLine {
  v: number
  agent?: string
  cli_version?: string
  type: "user" | "assistant"
  ts?: string
  id?: string
  content: unknown[]
}

/**
 * Extracted content from a unified transcript line's content array.
 */
interface ExtractedContent {
  text: string
  images: Array<{ mediaType: string; data: string }>
  toolCalls: ToolCall[]
}

/**
 * Detect whether content is in the unified transcript JSONL format.
 * Checks only the first line for performance.
 */
export function isUnifiedTranscript(content: string): boolean {
  const firstNewline = content.indexOf("\n")
  const firstLine = firstNewline === -1 ? content : content.slice(0, firstNewline)
  if (!firstLine.trim()) return false

  try {
    const obj = JSON.parse(firstLine)
    return (obj.type === "user" || obj.type === "assistant") && Array.isArray(obj.content)
  } catch {
    return false
  }
}

/**
 * Shared parser for the unified transcript.jsonl format.
 * All agents will eventually produce this format.
 */
export class UnifiedTranscriptParser implements TranscriptParser {
  readonly name = "UnifiedTranscript"
  readonly format = "jsonl" as const

  parse(jsonlContent: string) {
    return {
      messages: this.parseUnifiedTranscript(jsonlContent),
      isFallback: false,
    }
  }

  parseFrom(content: string, offset: number) {
    return jsonlParseFrom(this, content, offset)
  }

  strip(content: string): string {
    const lines = content.split("\n").filter((l) => l.trim())
    if (lines.length === 0) return content

    return lines
      .map((raw) => {
        try {
          const obj = JSON.parse(raw) as Record<string, unknown>
          return JSON.stringify({
            type: obj.type,
            ts: obj.ts,
            id: obj.id,
            content: obj.content,
          })
        } catch {
          return raw
        }
      })
      .join("\n")
  }

  /**
   * Extract text, images, and tool calls from a unified transcript content array.
   *
   * Content items come in two shapes:
   * - Text: { text: "...", type?: "text" } — type may be absent on user messages
   * - Image: { type: "image", source: { type: "base64", media_type, data } }
   * - Tool use: { id, name, input, type: "tool_use", result?: { output, status } }
   */
  private extractTextContent(
    content: unknown[],
    timestamp: string,
    filterSyntheticPreamble: boolean,
  ): ExtractedContent {
    let text = ""
    const images: Array<{ mediaType: string; data: string }> = []
    const toolCalls: ToolCall[] = []

    for (const block of content) {
      if (typeof block !== "object" || block === null) continue
      const b = block as Record<string, unknown>

      if (b.type === "tool_use" && b.name) {
        const result = b.result as Record<string, unknown> | undefined
        let toolResult: ToolCallResult | undefined
        if (result?.status) {
          const status = result.status as string
          toolResult = {
            type: status === "error" ? "error" : "text",
            output: (result.output as string) ?? "",
            error: status === "error" ? (result.output as string) : undefined,
          }
        }

        toolCalls.push({
          id: (b.id as string) ?? crypto.randomUUID(),
          name: b.name as string,
          input: (b.input as Record<string, unknown>) ?? {},
          timestamp,
          result: toolResult,
        })
      } else if (b.type === "image") {
        const source = b.source as Record<string, unknown> | undefined
        if (source?.type === "base64" && source.data && source.media_type) {
          images.push({
            mediaType: source.media_type as string,
            data: source.data as string,
          })
        }
      } else if (b.type === "text" || (!b.type && b.text)) {
        const blockText = (b.text as string) ?? ""
        if (filterSyntheticPreamble && isSyntheticInputText(blockText)) continue
        text += blockText
      }
    }
    text = text.replace(IMAGE_REFERENCE_PATTERN, "").trim()

    return { text, images, toolCalls }
  }

  /**
   * Parse unified transcript JSONL into TranscriptMessage[].
   *
   * Each line is a self-contained message (user or assistant) with an ISO
   * timestamp and a content array. Unlike legacy formats, consecutive assistant
   * lines are NOT merged — each line maps 1:1 to a TranscriptMessage.
   */
  private parseUnifiedTranscript(jsonlContent: string): TranscriptMessage[] {
    const lines = jsonlContent.split("\n").filter((line) => line.trim())
    const messages: TranscriptMessage[] = []
    const fallbackTs = new Date().toISOString()
    // Only strip synthetic wrappers until the first real user prompt has been
    // emitted. After that, pass user content through verbatim so a user
    // pasting wrapper-shaped content for discussion isn't silently dropped.
    let hasEmittedUserMessage = false

    for (const raw of lines) {
      let parsed: TranscriptLine
      try {
        parsed = JSON.parse(raw)
      } catch {
        continue
      }

      if (!parsed.type || !Array.isArray(parsed.content)) continue

      const timestamp = parsed.ts ?? fallbackTs

      if (parsed.type === "user") {
        const { text, images } = this.extractTextContent(
          parsed.content,
          timestamp,
          !hasEmittedUserMessage,
        )
        if (!text && images.length === 0) continue

        messages.push({
          id: ((parsed.content[0] as Record<string, unknown>)?.id as string) ?? crypto.randomUUID(),
          role: "user",
          content: text,
          timestamp,
          images: images.length > 0 ? images : undefined,
        })
        hasEmittedUserMessage = true
      } else if (parsed.type === "assistant") {
        const { text, images, toolCalls } = this.extractTextContent(
          parsed.content,
          timestamp,
          false,
        )

        messages.push({
          id: parsed.id ?? crypto.randomUUID(),
          role: "assistant",
          content: text,
          timestamp,
          images: images.length > 0 ? images : undefined,
          toolCalls,
        })
      }
    }

    return messages
  }
}

import type { ToolCall, ToolCallResult, ToolMixCategoryKey, TranscriptMessage } from "../../types"
import type { TranscriptParseResult, TranscriptParser } from "./types"

interface AmpLog {
  created?: number
  messages?: AmpMessage[]
  [key: string]: unknown
}

interface AmpMessage {
  role?: string
  messageId?: number | string
  timestamp?: string
  meta?: {
    sentAt?: number
  }
  usage?: {
    timestamp?: string
  }
  content?: AmpContentBlock[]
}

interface AmpContentBlock {
  type?: string
  text?: string
  id?: string
  name?: string
  input?: Record<string, unknown>
  startTime?: number
  finalTime?: number
  toolUseID?: string
  run?: {
    status?: string
    result?: unknown
  }
}

function parseAmpLog(content: string): AmpLog | null {
  try {
    const log = JSON.parse(content) as AmpLog
    if (!Array.isArray(log.messages)) return null
    return log
  } catch {
    return null
  }
}

function msToISO(ms: number | undefined, fallback: string): string {
  return typeof ms === "number" && Number.isFinite(ms) ? new Date(ms).toISOString() : fallback
}

function messageId(message: AmpMessage): string {
  if (message.messageId !== undefined) return String(message.messageId)
  return crypto.randomUUID()
}

function messageTimestamp(message: AmpMessage, fallback: string): string {
  if (typeof message.timestamp === "string" && message.timestamp) return message.timestamp
  if (typeof message.usage?.timestamp === "string" && message.usage.timestamp) {
    return message.usage.timestamp
  }
  if (typeof message.meta?.sentAt === "number") return msToISO(message.meta.sentAt, fallback)

  const firstTimedBlock = message.content?.find(
    (block) => typeof block.startTime === "number" || typeof block.finalTime === "number",
  )
  return msToISO(firstTimedBlock?.startTime ?? firstTimedBlock?.finalTime, fallback)
}

function blockTimestamp(block: AmpContentBlock, fallback: string): string {
  return msToISO(block.startTime ?? block.finalTime, fallback)
}

function extractText(content: AmpMessage["content"]): string {
  if (!Array.isArray(content)) return ""

  return content
    .flatMap((block) => {
      if (block.type !== "text") return []
      if (typeof block.text !== "string" || !block.text.trim()) return []
      return [block.text]
    })
    .join("\n")
    .trim()
}

function extractToolCalls(content: AmpMessage["content"], fallbackTimestamp: string): ToolCall[] {
  if (!Array.isArray(content)) return []

  return content
    .filter((block) => block.type === "tool_use" && typeof block.name === "string")
    .map((block) => ({
      id: block.id ?? crypto.randomUUID(),
      name: block.name!,
      input: block.input ?? {},
      timestamp: blockTimestamp(block, fallbackTimestamp),
    }))
}

function extractToolResults(messages: AmpMessage[]): Map<string, ToolCallResult> {
  const results = new Map<string, ToolCallResult>()

  for (const message of messages) {
    if (message.role !== "user" || !Array.isArray(message.content)) continue

    for (const block of message.content) {
      if (block.type !== "tool_result" || !block.toolUseID) continue
      results.set(block.toolUseID, parseToolResult(block.run))
    }
  }

  return results
}

function parseToolResult(run: AmpContentBlock["run"]): ToolCallResult {
  const result = run?.result
  const resultObject =
    typeof result === "object" && result !== null ? (result as Record<string, unknown>) : null
  const exitCode = typeof resultObject?.exitCode === "number" ? resultObject.exitCode : null
  const status = typeof run?.status === "string" ? run.status.toLowerCase() : null
  const isError =
    (status !== null && !["done", "success", "completed"].includes(status)) ||
    (exitCode !== null && exitCode !== 0)

  const output = extractToolOutput(result)
  const parsed: ToolCallResult = {
    type: isError ? "error" : "text",
  }

  if (resultObject && typeof resultObject.absolutePath === "string") {
    parsed.file = { filePath: resultObject.absolutePath }
  }

  if (output !== undefined) {
    parsed.output = output
  }

  if (isError) {
    parsed.error = output ?? run?.status ?? "Tool call failed"
  }

  return parsed
}

function extractToolOutput(result: unknown): string | undefined {
  if (typeof result === "string") return result
  if (typeof result !== "object" || result === null) return undefined

  const parsed = result as Record<string, unknown>
  if (typeof parsed.output === "string") return parsed.output
  if (typeof parsed.content === "string") return parsed.content
  if (typeof parsed.error === "string") return parsed.error

  return undefined
}

function parseAmpMessages(messages: AmpMessage[], sessionCreated: string): TranscriptMessage[] {
  const toolResultById = extractToolResults(messages)
  const result: TranscriptMessage[] = []

  let pendingAssistantText: string[] = []
  let pendingToolCalls: ToolCall[] = []
  let pendingTimestamp: string | null = null
  let pendingId: string | null = null

  const flushAssistant = () => {
    if (pendingAssistantText.length === 0 && pendingToolCalls.length === 0) {
      pendingTimestamp = null
      pendingId = null
      return
    }

    for (const toolCall of pendingToolCalls) {
      const toolResult = toolResultById.get(toolCall.id)
      if (toolResult) toolCall.result = toolResult
    }

    result.push({
      id: pendingId ?? crypto.randomUUID(),
      role: "assistant",
      content: pendingAssistantText.join("\n\n").trim(),
      timestamp: pendingTimestamp ?? sessionCreated,
      toolCalls: pendingToolCalls.length > 0 ? [...pendingToolCalls] : undefined,
    })

    pendingAssistantText = []
    pendingToolCalls = []
    pendingTimestamp = null
    pendingId = null
  }

  for (const message of messages) {
    const timestamp = messageTimestamp(message, sessionCreated)

    if (message.role === "user") {
      const text = extractText(message.content)
      if (!text) continue

      flushAssistant()
      result.push({
        id: messageId(message),
        role: "user",
        content: text,
        timestamp,
      })
      continue
    }

    if (message.role === "assistant") {
      if (!pendingTimestamp) pendingTimestamp = timestamp
      if (!pendingId) pendingId = messageId(message)

      const text = extractText(message.content)
      if (text) pendingAssistantText.push(text)
      pendingToolCalls.push(...extractToolCalls(message.content, timestamp))
    }
  }

  flushAssistant()
  return result
}

interface LineSpan {
  startLine: number
  endLine: number
}

function messageLineSpans(content: string, expectedMessageCount: number): LineSpan[] {
  const keyIndex = content.search(/"messages"\s*:/)
  if (keyIndex === -1) return []

  const arrayStartIndex = content.indexOf("[", keyIndex)
  if (arrayStartIndex === -1) return []

  let line = content.slice(0, arrayStartIndex).split("\n").length
  let inString = false
  let escaped = false
  let objectDepth = 0
  let startLine = 0
  const spans: LineSpan[] = []

  for (let index = arrayStartIndex + 1; index < content.length; index++) {
    const char = content[index]

    if (char === "\n") {
      line++
      escaped = false
      continue
    }

    if (inString) {
      if (escaped) {
        escaped = false
      } else if (char === "\\") {
        escaped = true
      } else if (char === '"') {
        inString = false
      }
      continue
    }

    if (char === '"') {
      inString = true
      continue
    }

    if (objectDepth === 0) {
      if (char === "{") {
        objectDepth = 1
        startLine = line
      } else if (char === "]") {
        break
      }
      continue
    }

    if (char === "{") {
      objectDepth++
      continue
    }

    if (char === "}") {
      objectDepth--
      if (objectDepth === 0) {
        spans.push({ startLine, endLine: line })
        if (spans.length === expectedMessageCount) return spans
      }
    }
  }

  return spans
}

function indexForOffset(content: string, offset: number, messages: AmpMessage[]): number {
  if (offset <= 0) return 0

  const lines = content.split("\n")
  if (lines.length <= 1) {
    return offset <= messages.length ? offset : messages.length
  }

  const spans = messageLineSpans(content, messages.length)
  if (spans.length === messages.length) {
    const index = spans.findIndex((span) => span.endLine >= offset)
    return index === -1 ? messages.length : index
  }

  return offset <= messages.length ? offset : 0
}

function sliceAmpLogForStorage(content: string, offset: number): string {
  const log = parseAmpLog(content)
  if (!log) return content

  const startIndex = indexForOffset(content, offset, log.messages!)
  if (startIndex <= 0) return content

  const slicedMessages = log.messages!.slice(startIndex)
  if (slicedMessages.length === 0) return content

  return JSON.stringify({
    ...log,
    messages: slicedMessages,
  })
}

function stripAmpMessages(messages: AmpMessage[], sessionCreated: string): AmpMessage[] {
  return messages.map((message) => ({
    role: message.role,
    messageId: message.messageId,
    timestamp: messageTimestamp(message, sessionCreated),
    meta:
      typeof message.meta?.sentAt === "number"
        ? {
            sentAt: message.meta.sentAt,
          }
        : undefined,
    content: Array.isArray(message.content)
      ? message.content.flatMap((block) => stripAmpContentBlock(block))
      : undefined,
  }))
}

function stripAmpContentBlock(block: AmpContentBlock): AmpContentBlock[] {
  if (block.type === "thinking") return []

  if (block.type === "tool_use") {
    return [
      {
        type: "tool_use",
        id: block.id,
        name: block.name,
        input: block.input,
        startTime: block.startTime,
        finalTime: block.finalTime,
      },
    ]
  }

  if (block.type === "tool_result") {
    return [
      {
        type: "tool_result",
        toolUseID: block.toolUseID,
        run: block.run
          ? {
              status: block.run.status,
              result: block.run.result,
            }
          : undefined,
      },
    ]
  }

  if (block.type === "text") {
    return [
      {
        type: "text",
        text: block.text,
        startTime: block.startTime,
        finalTime: block.finalTime,
      },
    ]
  }

  return []
}

/**
 * Parser for Amp transcripts.
 *
 * Amp writes a pretty-printed JSON object with a messages array, even though
 * the file extension used by the current adapter is `.jsonl`.
 */
export class AmpParser implements TranscriptParser {
  readonly name = "Amp"
  readonly format = "json" as const

  parse(content: string): TranscriptParseResult {
    const log = parseAmpLog(content)
    if (!log) return { messages: [], isFallback: false }

    const sessionCreated = msToISO(log.created, new Date().toISOString())
    return {
      messages: parseAmpMessages(log.messages!, sessionCreated),
      isFallback: false,
    }
  }

  parseFrom(content: string, offset: number): TranscriptParseResult {
    const log = parseAmpLog(content)
    if (!log) return { messages: [], isFallback: false }

    const sessionCreated = msToISO(log.created, new Date().toISOString())
    const startIndex = indexForOffset(content, offset, log.messages!)
    return {
      messages: parseAmpMessages(log.messages!.slice(startIndex), sessionCreated),
      isFallback: false,
    }
  }

  sliceForStorage(content: string, offset: number): string {
    return sliceAmpLogForStorage(content, offset)
  }

  strip(content: string): string {
    const log = parseAmpLog(content)
    if (!log) return content

    const sessionCreated = msToISO(log.created, new Date().toISOString())
    return JSON.stringify({
      created: log.created,
      messages: stripAmpMessages(log.messages!, sessionCreated),
    })
  }

  classifyTool(call: ToolCall): ToolMixCategoryKey {
    const name = call.name
    if (name === "Bash" || name === "bash" || name === "shell") return "shell"
    if (
      name === "Read" ||
      name === "Write" ||
      name === "Edit" ||
      name === "create_file" ||
      name === "update_file" ||
      name === "delete_file"
    ) {
      return "fileOps"
    }
    if (name === "Grep" || name === "Glob" || name === "list_directory") return "search"
    return "other"
  }

  extractSkillFromTool(_call: ToolCall): string | null {
    return null
  }

  extractMcpServerFromTool(_call: ToolCall): string | null {
    return null
  }
}

import type { TranscriptMessage } from "../../types"
import type { TranscriptParser, TranscriptParseResult } from "./types"
import { jsonlParseFrom } from "./types"

const USER_QUERY_PATTERN = /<user_query[^>]*>(.*?)<\/user_query>/s

/**
 * Extract the user's text from Cursor's <user_query> wrapper.
 * Falls back to the raw text if no wrapper is found.
 */
function extractUserQuery(text: string): string {
  const match = text.match(USER_QUERY_PATTERN)
  return (match ? match[1] : text).trim()
}

/**
 * Extract plain text from a Cursor message content array.
 */
function extractText(content: unknown): string {
  if (typeof content === "string") return content
  if (!Array.isArray(content)) return ""

  const parts: string[] = []
  for (const block of content) {
    if (typeof block === "object" && block !== null) {
      const b = block as Record<string, unknown>
      if (b.type === "text" && typeof b.text === "string") {
        parts.push(b.text)
      }
    }
  }
  return parts.join("\n")
}

/**
 * Parse a Cursor JSONL transcript into TranscriptMessage[].
 *
 * Cursor format: each line is `{"role":"user"|"assistant","message":{"content":[...]}}`.
 * User text is wrapped in `<user_query>` tags.
 * Consecutive assistant messages are merged into a single turn.
 */
function parseCursorTranscript(jsonlContent: string): TranscriptMessage[] {
  const lines = jsonlContent
    .split("\n")
    .map((line) => line.trim())
    .filter(Boolean)
  const result: TranscriptMessage[] = []

  let pendingAssistantParts: string[] = []

  const flushAssistant = () => {
    if (pendingAssistantParts.length === 0) return
    const content = pendingAssistantParts.join("\n\n").trim()
    if (content) {
      result.push({
        id: crypto.randomUUID(),
        role: "assistant",
        content,
        timestamp: new Date().toISOString(),
      })
    }
    pendingAssistantParts = []
  }

  for (const line of lines) {
    let parsed: Record<string, unknown>
    try {
      parsed = JSON.parse(line)
    } catch {
      continue
    }

    const role = parsed.role as string | undefined
    const message = parsed.message as Record<string, unknown> | undefined
    if (!role || !message?.content) continue

    const rawText = extractText(message.content)
    if (!rawText.trim()) continue

    if (role === "user") {
      flushAssistant()
      const content = extractUserQuery(rawText)
      if (content) {
        result.push({
          id: crypto.randomUUID(),
          role: "user",
          content,
          timestamp: new Date().toISOString(),
        })
      }
    } else if (role === "assistant") {
      pendingAssistantParts.push(rawText.trim())
    }
  }

  // Flush any remaining assistant content
  flushAssistant()

  return result
}

/**
 * Parser for Cursor JSONL transcripts.
 */
export class CursorParser implements TranscriptParser {
  readonly name = "Cursor"
  readonly format = "jsonl" as const

  parse(jsonlContent: string): TranscriptParseResult {
    const messages = parseCursorTranscript(jsonlContent)

    return {
      messages,
      isFallback: false,
    }
  }

  parseFrom(content: string, offset: number): TranscriptParseResult {
    return jsonlParseFrom(this, content, offset)
  }
}

import type { TranscriptMessage, TranscriptRuntimeTag, ToolCall, ToolCallResult } from "../../types"
import { extractRuntimeTags, extractToolUseBlocks } from "./common"
import type { TranscriptParser, TranscriptParseResult } from "./types"
import { jsonlParseFrom } from "./types"

/**
 * Extract text and image content from Droid message content blocks.
 * Droid content is always an array of blocks (never a plain string).
 */
interface ExtractedContent {
  text: string
  images: Array<{ mediaType: string; data: string }>
  hasToolResults: boolean
}

function extractTextContent(content: unknown): ExtractedContent {
  if (!Array.isArray(content)) {
    return { text: "", images: [], hasToolResults: false }
  }

  let text = ""
  const images: Array<{ mediaType: string; data: string }> = []
  let hasToolResults = false

  for (const block of content) {
    if (typeof block !== "object" || block === null) continue
    const b = block as Record<string, unknown>

    if (b.type === "text") {
      text += (b.text as string) || ""
    } else if (b.type === "tool_result") {
      hasToolResults = true
    } else if (b.type === "image") {
      const source = b.source as Record<string, unknown> | undefined
      if (source?.type === "base64" && source.data && source.media_type) {
        images.push({
          mediaType: source.media_type as string,
          data: source.data as string,
        })
      }
    }
  }

  return { text: text.trim(), images, hasToolResults }
}

/**
 * Extract tool_result entries from a user message's content array.
 * Returns a map of tool_use_id → ToolCallResult.
 *
 * Droid tool_result blocks have the shape:
 * { type: "tool_result", tool_use_id: "...", content: "..." }
 * where content is the tool output string.
 */
function extractToolResults(content: unknown): Map<string, ToolCallResult> {
  const results = new Map<string, ToolCallResult>()
  if (!Array.isArray(content)) return results

  for (const block of content) {
    if (typeof block !== "object" || block === null) continue
    const b = block as Record<string, unknown>
    if (b.type !== "tool_result" || !b.tool_use_id) continue

    const resultContent = b.content
    const isError = b.is_error === true

    const result: ToolCallResult = {
      type: isError ? "error" : "text",
    }

    if (typeof resultContent === "string") {
      if (isError) {
        result.error = resultContent
      } else {
        result.output = resultContent
      }
    }

    results.set(b.tool_use_id as string, result)
  }

  return results
}

/**
 * Strip Droid internal tags from message content.
 * Extends shared system tag stripping with Droid-specific <thinking> tag removal
 * (emitted by Gemini models running inside Droid).
 */
function stripInternalTags(content: string): {
  content: string
  runtimeTags: TranscriptRuntimeTag[]
} {
  const stripped = extractRuntimeTags(content)
  return {
    content: stripped.content.replace(/<thinking>[\s\S]*?<\/thinking>/g, "").trim(),
    runtimeTags: stripped.runtimeTags,
  }
}

/**
 * Noise user messages generated by Droid when sessions are interrupted.
 * These are not real user prompts and should be filtered out.
 */
const NOISE_USER_MESSAGES = new Set([
  "request interrupted by user",
  "error: request was aborted.",
  "request cancelled by user",
])

/**
 * Parse Droid JSONL transcript into TranscriptMessage[].
 *
 * Droid format: each line is a JSON object with:
 * - type: "session_start" (skip) or "message"
 * - For messages: id, timestamp, message.role, message.content (array of blocks)
 * - parentId for threading (ignored — messages are chronologically ordered)
 */
function parseDroidTranscript(jsonlContent: string): TranscriptMessage[] {
  const lines = jsonlContent.split("\n").filter((line) => line.trim())

  // Pass 1: Collect tool_result data from user messages for later correlation
  const toolResultById = new Map<string, ToolCallResult>()

  for (const line of lines) {
    let parsed: Record<string, unknown>
    try {
      parsed = JSON.parse(line)
    } catch {
      continue
    }

    if (parsed.type !== "message") continue

    const message = parsed.message as Record<string, unknown> | undefined
    if (!message || message.role !== "user") continue

    const results = extractToolResults(message.content)
    for (const [id, result] of results) {
      toolResultById.set(id, result)
    }
  }

  // Pass 2: Build message list
  const messages: TranscriptMessage[] = []

  for (const line of lines) {
    let parsed: Record<string, unknown>
    try {
      parsed = JSON.parse(line)
    } catch {
      continue
    }

    if (parsed.type !== "message") continue

    const message = parsed.message as Record<string, unknown> | undefined
    if (!message) continue

    const role = message.role as string
    const id = (parsed.id as string) || crypto.randomUUID()
    const timestamp = (parsed.timestamp as string) || new Date().toISOString()

    if (role === "user") {
      const { text, images, hasToolResults } = extractTextContent(message.content)

      // Skip user messages that are only tool results with no text/images
      if (hasToolResults && !text && images.length === 0) continue

      const { content, runtimeTags } = stripInternalTags(text)
      if (!content && images.length === 0 && runtimeTags.length === 0) continue

      // Skip noise messages from session interruptions
      if (NOISE_USER_MESSAGES.has(content.toLowerCase())) continue

      messages.push({
        id,
        role: "user",
        content,
        timestamp,
        images: images.length > 0 ? images : undefined,
        runtimeTags: runtimeTags.length > 0 ? runtimeTags : undefined,
      })
    } else if (role === "assistant") {
      const { text, images } = extractTextContent(message.content)
      const { content, runtimeTags } = stripInternalTags(text)

      // Extract tool calls and attach results from pass 1
      const toolUses = extractToolUseBlocks(message.content)
      const toolCalls: ToolCall[] = toolUses.map((tu) => ({
        ...tu,
        timestamp,
        result: toolResultById.get(tu.id),
      }))

      // Skip assistant messages with no visible content and no tool calls
      if (!content && toolCalls.length === 0 && images.length === 0 && runtimeTags.length === 0)
        continue

      messages.push({
        id,
        role: "assistant",
        content,
        timestamp,
        toolCalls: toolCalls.length > 0 ? toolCalls : undefined,
        images: images.length > 0 ? images : undefined,
        runtimeTags: runtimeTags.length > 0 ? runtimeTags : undefined,
      })
    }
  }

  return messages
}

/**
 * Parser for Factory AI Droid JSONL transcripts.
 */
export class DroidParser implements TranscriptParser {
  readonly name = "Droid"
  readonly format = "jsonl" as const

  parse(jsonlContent: string): TranscriptParseResult {
    const messages = parseDroidTranscript(jsonlContent)

    return {
      messages,
      isFallback: false,
    }
  }

  parseFrom(content: string, offset: number): TranscriptParseResult {
    return jsonlParseFrom(this, content, offset)
  }
}

import type { TranscriptMessage, ToolCall, ToolCallResult } from "../../types"
import type { TranscriptParser, TranscriptParseResult } from "./types"

/**
 * Kiro transcript parser — handles two distinct formats:
 *
 * 1. **Kiro CLI** — turn-pair entries: `{ user: { content: { Prompt: ... } }, assistant: { Response: ... } }`
 * 2. **Kiro IDE** — flat message entries: `{ message: { role: "user"|"assistant", content: ... } }`
 *
 * Both formats wrap their data in `{ history: [...] }`.
 * Despite the `.jsonl` extension, the content is a single JSON object.
 */

interface KiroToolUse {
  id: string
  name: string
  args: Record<string, unknown>
}

interface KiroToolUseResult {
  tool_use_id: string
  content: Array<{ Text?: string }>
  status: string
}

interface KiroUserContent {
  Prompt?: { prompt: string }
  ToolUseResults?: { tool_use_results: KiroToolUseResult[] }
}

interface KiroAssistantContent {
  ToolUse?: {
    message_id: string
    content: string
    tool_uses: KiroToolUse[]
  }
  Response?: {
    message_id: string
    content: string
  }
}

interface KiroCliHistoryEntry {
  user: {
    content: KiroUserContent
    timestamp: string | null
    images: Array<{ media_type: string; data: string }> | null
  }
  assistant: KiroAssistantContent
  request_metadata?: Record<string, unknown>
}

interface KiroIdeHistoryEntry {
  message: {
    role: "user" | "assistant"
    content: string | Array<{ type: string; text: string }>
    id?: string
  }
  contextItems?: unknown[]
  editorState?: unknown
  promptLogs?: unknown[]
  executionId?: string
}

type KiroHistoryEntry = KiroCliHistoryEntry | KiroIdeHistoryEntry

interface KiroTranscript {
  conversation_id?: string
  history: KiroHistoryEntry[]
}

/** Detect whether a history entry is from the IDE (has `message`) or CLI (has `user`). */
function isIdeEntry(entry: KiroHistoryEntry): entry is KiroIdeHistoryEntry {
  return "message" in entry && entry.message != null
}

function parseKiroTranscript(content: string): KiroTranscript | null {
  try {
    const parsed = JSON.parse(content) as KiroTranscript
    if (!Array.isArray(parsed.history)) return null
    return parsed
  } catch {
    return null
  }
}

function buildCliMessages(history: KiroCliHistoryEntry[]): TranscriptMessage[] {
  // Pass 1: Collect tool results by tool_use_id
  const toolResultById = new Map<string, ToolCallResult>()
  for (const entry of history) {
    const toolResults = entry.user.content?.ToolUseResults?.tool_use_results
    if (!toolResults) continue
    for (const result of toolResults) {
      const textParts = result.content
        .map((c) => c.Text ?? "")
        .filter(Boolean)
        .join("\n")
      toolResultById.set(result.tool_use_id, {
        type: result.status === "Success" ? "text" : "error",
        output: textParts || undefined,
        error: result.status !== "Success" ? result.status : undefined,
      })
    }
  }

  // Pass 2: Build messages
  const messages: TranscriptMessage[] = []
  let lastTimestamp = new Date().toISOString()

  for (const entry of history) {
    const userContent = entry.user.content
    const timestamp = entry.user.timestamp ?? lastTimestamp
    if (entry.user.timestamp) {
      lastTimestamp = entry.user.timestamp
    }

    // Emit user message if this is a Prompt (skip ToolUseResults-only turns and null content)
    if (userContent?.Prompt) {
      const prompt = userContent.Prompt.prompt.trim()
      if (prompt) {
        messages.push({
          id: crypto.randomUUID(),
          role: "user",
          content: prompt,
          timestamp,
          images: entry.user.images?.map((img) => ({
            mediaType: img.media_type,
            data: img.data,
          })),
        })
      }
    }

    // Collect tool calls from ToolUse
    const toolCalls: ToolCall[] = []
    const assistant = entry.assistant

    if (assistant.ToolUse) {
      for (const tu of assistant.ToolUse.tool_uses) {
        toolCalls.push({
          id: tu.id,
          name: tu.name,
          input: tu.args,
          timestamp,
          result: toolResultById.get(tu.id),
        })
      }
    }

    // Emit assistant message
    const assistantText = assistant.Response?.content ?? assistant.ToolUse?.content ?? ""
    const trimmedText = assistantText.trim()

    // Emit if there's text or tool calls
    if (trimmedText || toolCalls.length > 0) {
      messages.push({
        id: assistant.Response?.message_id ?? assistant.ToolUse?.message_id ?? crypto.randomUUID(),
        role: "assistant",
        content: trimmedText,
        timestamp,
        toolCalls: toolCalls.length > 0 ? toolCalls : undefined,
      })
    }
  }

  return messages
}

/** Extract plain text from Kiro IDE message content (string or content-block array). */
function extractIdeText(content: string | Array<{ type: string; text: string }>): string {
  if (typeof content === "string") return content
  return content
    .filter((block) => block.type === "text")
    .map((block) => block.text)
    .join("\n")
}

/**
 * Build TranscriptMessages from Kiro IDE history entries.
 * IDE entries are flat (one entry per message, not turn-pairs).
 */
function buildIdeMessages(history: KiroIdeHistoryEntry[]): TranscriptMessage[] {
  const messages: TranscriptMessage[] = []

  for (const entry of history) {
    const { message } = entry
    const text = extractIdeText(message.content).trim()
    if (!text) continue

    messages.push({
      id: message.id ?? crypto.randomUUID(),
      role: message.role,
      content: text,
      timestamp: new Date().toISOString(),
    })
  }

  return messages
}

function buildMessages(history: KiroHistoryEntry[]): TranscriptMessage[] {
  if (history.length === 0) return []

  // Detect format from the first entry
  if (isIdeEntry(history[0])) {
    return buildIdeMessages(history as KiroIdeHistoryEntry[])
  }
  return buildCliMessages(history as KiroCliHistoryEntry[])
}

/**
 * Parser for Kiro session transcripts (single JSON with history array).
 */
export class KiroParser implements TranscriptParser {
  readonly name = "Kiro"
  readonly format = "json" as const

  parse(content: string): TranscriptParseResult {
    const transcript = parseKiroTranscript(content)
    if (!transcript) return { messages: [], isFallback: false }

    return {
      messages: buildMessages(transcript.history),
      isFallback: false,
    }
  }

  parseFrom(content: string, offset: number): TranscriptParseResult {
    const transcript = parseKiroTranscript(content)
    if (!transcript) return { messages: [], isFallback: false }

    const entries = offset > 0 ? transcript.history.slice(offset) : transcript.history

    return {
      messages: buildMessages(entries),
      isFallback: false,
    }
  }

  strip(content: string): string {
    let parsed: Record<string, unknown>
    try {
      parsed = JSON.parse(content)
    } catch {
      return content
    }

    const history = parsed.history as KiroHistoryEntry[] | undefined
    if (!Array.isArray(history) || history.length === 0) {
      return JSON.stringify({ history: [] })
    }

    // Detect format from first entry
    const isIde = isIdeEntry(history[0])

    if (isIde) {
      const stripped: Record<string, unknown> = {
        history: (history as KiroIdeHistoryEntry[]).map((entry) => ({
          message: {
            role: entry.message.role,
            content: extractIdeText(entry.message.content),
            id: entry.message.id,
          },
        })),
      }
      return JSON.stringify(stripped)
    }

    // CLI format: strip request_metadata, file_text from tool args, and top-level bloat
    const stripped: Record<string, unknown> = {
      conversation_id: parsed.conversation_id,
      history: (history as KiroCliHistoryEntry[]).map((entry) => {
        const { request_metadata: _, ...rest } = entry

        // Strip file_text from tool args (can be very large)
        if (rest.assistant?.ToolUse?.tool_uses) {
          rest.assistant = {
            ...rest.assistant,
            ToolUse: {
              ...rest.assistant.ToolUse,
              tool_uses: rest.assistant.ToolUse.tool_uses.map((tu) => ({
                ...tu,
                args: { ...tu.args, file_text: undefined },
              })),
            },
          }
        }

        return rest
      }),
    }

    return JSON.stringify(stripped)
  }
}

import type { TranscriptMessage, ToolCall, ToolCallResult } from "../../types"
import type { TranscriptParser, TranscriptParseResult } from "./types"

/**
 * Copilot CLI JSONL event structure.
 * Each line is: { type, data, id, timestamp, parentId }
 *
 * Known event types:
 * - session.start, session.model_change — session metadata
 * - user.message — user prompts
 * - assistant.turn_start, assistant.message, assistant.turn_end — assistant turns
 * - tool.execution_start, tool.execution_complete — tool lifecycle
 */
interface CopilotEvent {
  type: string
  data: Record<string, unknown>
  id: string
  timestamp: string
  parentId: string | null
}

/**
 * Tool request as it appears in assistant.message data.toolRequests[].
 * Field names match the real Copilot CLI JSONL format.
 */
interface CopilotToolRequest {
  toolCallId?: string
  name?: string
  arguments?: Record<string, unknown>
}

/**
 * Parse a Copilot CLI JSONL transcript into TranscriptMessage[].
 *
 * Copilot CLI format: each line is a JSON object with:
 * - type: "session.start" | "user.message" | "assistant.turn_start" | "assistant.message" | "assistant.turn_end"
 * - data: event-specific payload
 * - id: UUID
 * - timestamp: ISO 8601
 * - parentId: UUID or null
 *
 * user.message → data.content (string)
 * assistant.message → data.content (string), data.toolRequests (array), data.reasoningText (string)
 * assistant.turn_start / assistant.turn_end → turn boundaries (used for grouping)
 */
function parseCopilotCliTranscript(jsonlContent: string): TranscriptMessage[] {
  const lines = jsonlContent
    .split("\n")
    .map((line) => line.trim())
    .filter(Boolean)

  const result: TranscriptMessage[] = []

  // Track current turn's assistant content and tool calls
  let pendingAssistantParts: string[] = []
  let pendingToolCalls: ToolCall[] = []
  let pendingTimestamp: string | null = null
  let pendingId: string | null = null

  const flushAssistant = () => {
    if (pendingAssistantParts.length === 0 && pendingToolCalls.length === 0) {
      pendingTimestamp = null
      pendingId = null
      return
    }
    const content = pendingAssistantParts.join("\n\n").trim()
    if (content || pendingToolCalls.length > 0) {
      result.push({
        id: pendingId ?? crypto.randomUUID(),
        role: "assistant",
        content,
        timestamp: pendingTimestamp ?? new Date().toISOString(),
        toolCalls: pendingToolCalls.length > 0 ? [...pendingToolCalls] : undefined,
      })
    }
    pendingAssistantParts = []
    pendingToolCalls = []
    pendingTimestamp = null
    pendingId = null
  }

  for (const line of lines) {
    let event: CopilotEvent
    try {
      event = JSON.parse(line)
    } catch {
      continue
    }

    if (!event.type || !event.data) continue

    switch (event.type) {
      case "user.message": {
        // Flush any pending assistant content before a new user message
        flushAssistant()

        const content = typeof event.data.content === "string" ? event.data.content.trim() : ""
        if (content) {
          result.push({
            id: event.id ?? crypto.randomUUID(),
            role: "user",
            content,
            timestamp: event.timestamp ?? new Date().toISOString(),
          })
        }
        break
      }

      case "assistant.message": {
        const content = typeof event.data.content === "string" ? event.data.content.trim() : ""
        if (content) {
          pendingAssistantParts.push(content)
        }

        // Set timestamp from first assistant.message in this turn
        if (!pendingTimestamp) {
          pendingTimestamp = event.timestamp ?? new Date().toISOString()
        }
        if (!pendingId) {
          pendingId = event.id
        }

        // Extract tool requests
        const toolRequests = event.data.toolRequests as CopilotToolRequest[] | undefined
        if (Array.isArray(toolRequests)) {
          for (const tr of toolRequests) {
            if (tr.name) {
              pendingToolCalls.push({
                id: tr.toolCallId ?? crypto.randomUUID(),
                name: tr.name,
                input: tr.arguments ?? {},
                timestamp: event.timestamp ?? new Date().toISOString(),
              })
            }
          }
        }
        break
      }

      case "tool.execution_complete": {
        // Match tool result back to pending tool call by toolCallId
        const toolCallId = event.data.toolCallId as string | undefined
        if (toolCallId) {
          const matchingCall = pendingToolCalls.find((tc) => tc.id === toolCallId)
          if (matchingCall) {
            const success = event.data.success as boolean | undefined
            const error = event.data.error as { message?: string } | undefined
            const resultData = event.data.result as { content?: string } | undefined

            const toolResult: ToolCallResult = {
              type: success === false ? "error" : "text",
            }
            if (error?.message) {
              toolResult.error = error.message
            }
            if (resultData?.content) {
              toolResult.output = resultData.content
            }
            matchingCall.result = toolResult
          }
        }
        break
      }

      case "assistant.turn_end": {
        // Flush assistant content at end of turn
        flushAssistant()
        break
      }

      // session.start, session.model_change, assistant.turn_start,
      // tool.execution_start are metadata — skip
      default:
        break
    }
  }

  // Flush any remaining assistant content (in case no turn_end at EOF)
  flushAssistant()

  return result
}

/**
 * Parser for GitHub Copilot CLI JSONL transcripts.
 */
export class CopilotCliParser implements TranscriptParser {
  readonly name = "Copilot CLI"
  readonly format = "jsonl" as const

  parse(jsonlContent: string): TranscriptParseResult {
    const messages = parseCopilotCliTranscript(jsonlContent)

    return {
      messages,
      isFallback: false,
    }
  }
}

import type { TranscriptMessage, ToolCall } from "../../types"
import type { TranscriptParser, TranscriptParseResult } from "./types"

interface OpenCodePart {
  type: string
  text?: string
  tool?: string
  state?: {
    input?: unknown
    output?: string
    status?: string
    time?: { start?: number; end?: number }
  }
  time?: { start?: number; end?: number }
}

interface OpenCodeMessage {
  info: {
    role: "user" | "assistant"
    time?: { created?: number; completed?: number }
    id?: string
  }
  parts: OpenCodePart[]
}

interface OpenCodeLog {
  info?: {
    time?: {
      created?: number
    }
  }
  messages: OpenCodeMessage[]
}

function msToISO(ms: number | undefined, fallback: string): string {
  return ms != null ? new Date(ms).toISOString() : fallback
}

/**
 * Group and convert raw OpenCode messages into TranscriptMessages.
 * Consecutive assistant messages are merged into a single turn.
 */
function parseOpenCodeMessages(
  rawMessages: OpenCodeMessage[],
  sessionCreated: string,
): TranscriptMessage[] {
  const result: TranscriptMessage[] = []

  // Group consecutive assistant messages into a single turn
  let i = 0
  while (i < rawMessages.length) {
    const msg = rawMessages[i]
    const role = msg.info?.role

    if (role === "user") {
      const text = msg.parts
        .filter((p) => p.type === "text")
        .map((p) => p.text ?? "")
        .join("\n")
        .trim()

      if (text) {
        result.push({
          id: msg.info.id ?? crypto.randomUUID(),
          role: "user",
          content: text,
          timestamp: msToISO(msg.info.time?.created, sessionCreated),
        })
      }
      i++
    } else if (role === "assistant") {
      // Collect consecutive assistant messages as one turn
      const toolCalls: ToolCall[] = []
      let assistantText = ""
      const turnTimestamp = msToISO(msg.info.time?.created, sessionCreated)
      let turnId = msg.info.id ?? crypto.randomUUID()

      while (i < rawMessages.length && rawMessages[i].info?.role === "assistant") {
        const assistantMsg = rawMessages[i]
        const msgTs = msToISO(assistantMsg.info.time?.created, sessionCreated)

        // Use the last assistant message's id if it has one
        if (assistantMsg.info.id) {
          turnId = assistantMsg.info.id
        }

        for (const part of assistantMsg.parts) {
          if (part.type === "tool" && part.tool) {
            const toolTs = msToISO(part.state?.time?.start, msgTs)
            toolCalls.push({
              id: crypto.randomUUID(),
              name: part.tool,
              input: (part.state?.input as Record<string, unknown>) ?? {},
              timestamp: toolTs,
              result: part.state?.status
                ? {
                    type: part.state.status === "error" ? "error" : "text",
                    output: part.state.output ?? "",
                    error: part.state.status === "error" ? part.state.output : undefined,
                  }
                : undefined,
            })
          } else if (part.type === "text" && part.text) {
            // Last text part wins as the final assistant response
            assistantText = part.text
          }
        }
        i++
      }

      result.push({
        id: turnId,
        role: "assistant",
        content: assistantText.trim(),
        timestamp: turnTimestamp,
        toolCalls,
      })
    } else {
      i++
    }
  }

  return result
}

function parseOpenCodeLog(content: string): OpenCodeLog | null {
  try {
    const log: OpenCodeLog = JSON.parse(content)
    if (!Array.isArray(log.messages)) return null
    return log
  } catch {
    return null
  }
}

/**
 * Parser for OpenCode session logs (single JSON with messages array).
 */
export class OpenCodeParser implements TranscriptParser {
  readonly name = "OpenCode"
  readonly format = "json" as const

  parse(content: string): TranscriptParseResult {
    return this.parseFrom(content, 0)
  }

  parseFrom(content: string, offset: number): TranscriptParseResult {
    const log = parseOpenCodeLog(content)
    if (!log) return { messages: [], isFallback: false }

    const sessionCreated = msToISO(log.info?.time?.created, new Date().toISOString())

    // Slice raw messages BEFORE grouping, matching CLI's countTranscriptItems
    // which counts raw messages (not grouped turns)
    const msgs = offset > 0 ? log.messages.slice(offset) : log.messages

    return {
      messages: parseOpenCodeMessages(msgs, sessionCreated),
      isFallback: false,
    }
  }

  /**
   * Strip an OpenCode transcript to only the fields parse() reads.
   * Drops: top-level metadata (slug, summary, etc.), per-message summaries
   * (which contain full file diffs), and per-message agent/model metadata.
   */
  strip(content: string): string {
    let log: Record<string, unknown>
    try {
      log = JSON.parse(content)
    } catch {
      return content
    }

    const info = log.info as Record<string, unknown> | undefined
    const stripped: Record<string, unknown> = {
      // Only keep info.time.created (needed for session timestamp fallback)
      info: info?.time
        ? { time: { created: (info.time as Record<string, unknown>).created } }
        : undefined,
      messages: Array.isArray(log.messages)
        ? (log.messages as Array<Record<string, unknown>>).map((msg) => {
            const msgInfo = msg.info as Record<string, unknown> | undefined
            return {
              info: msgInfo
                ? { role: msgInfo.role, time: msgInfo.time, id: msgInfo.id }
                : undefined,
              parts: msg.parts,
            }
          })
        : [],
    }

    return JSON.stringify(stripped)
  }
}

import { ClaudeCodeParser } from "./claude-code-parser"
import type { TranscriptParser, TranscriptParseResult } from "./types"

/**
 * Fallback parser for unknown agents.
 * Delegates to ClaudeCodeParser for best-effort parsing (the Anthropic API
 * message format is common across agents using the checkpoint protocol)
 * but marks the result as a fallback so the frontend can show a warning.
 */
const FALLBACK_WARNING =
  "Full transcript parsing is not yet available for this agent. Some messages or tool calls may not display correctly."

export class FallbackParser implements TranscriptParser {
  readonly name = "Fallback"
  readonly format = "jsonl" as const
  private delegate = new ClaudeCodeParser()

  private asFallback(result: TranscriptParseResult): TranscriptParseResult {
    return { messages: result.messages, isFallback: true, warning: FALLBACK_WARNING }
  }

  parse(jsonlContent: string): TranscriptParseResult {
    return this.asFallback(this.delegate.parse(jsonlContent))
  }

  parseFrom(content: string, offset: number): TranscriptParseResult {
    return this.asFallback(this.delegate.parseFrom(content, offset))
  }
}

// ─── Text cleaning ────────────────────────────────────────────────────────────

// Strip markdown code fences and inline code spans from assistant content.
// We index the conversation — what was discussed — not the code itself.
export function stripCodeFromText(text: string): string {
  return (
    text
      // Fenced blocks: ```lang?\n...\n``` or ~~~\n...\n~~~
      .replace(/^```[^\n]*\n[\s\S]*?^```[ \t]*$/gm, "")
      .replace(/^~~~[^\n]*\n[\s\S]*?^~~~[ \t]*$/gm, "")
