import type { ToolUseBlock, TranscriptRuntimeTag } from "../../types"

const SYSTEM_TAG_NAMES = [
  "command-message",
  "command-name",
  "command-args",
  "local-command-caveat",
  "system-reminder",
] as const satisfies readonly TranscriptRuntimeTag["tag"][]

const SYSTEM_TAG_PATTERN = new RegExp(`<(${SYSTEM_TAG_NAMES.join("|")})>([\\s\\S]*?)<\\/\\1>`, "g")

/** Extract tool_use blocks from message content array. */
export function extractToolUseBlocks(content: unknown): ToolUseBlock[] {
  if (!Array.isArray(content)) return []

  const toolUses: ToolUseBlock[] = []
  for (const block of content) {
    if (typeof block !== "object" || block === null) continue
    const b = block as Record<string, unknown>
    if (b.type === "tool_use" && b.id && b.name) {
      toolUses.push({
        id: b.id as string,
        name: b.name as string,
        input: (b.input as Record<string, unknown>) || {},
      })
    }
  }
  return toolUses
}

/**
 * Strip system-injected XML tags from message content.
 * These tags are injected by the runtime and should never be shown to users.
 * Does NOT trim — callers can chain additional replacements before trimming.
 */
export function stripSystemTags(content: string): string {
  return extractRuntimeTags(content).content
}

export function extractRuntimeTags(content: string): {
  content: string
  runtimeTags: TranscriptRuntimeTag[]
} {
  const runtimeTags: TranscriptRuntimeTag[] = []
  const stripped = content.replace(
    SYSTEM_TAG_PATTERN,
    (_match, tag: TranscriptRuntimeTag["tag"], body: string) => {
      runtimeTags.push({ tag, content: body.trim() })
      return ""
    },
  )
  return { content: stripped, runtimeTags }
}

/**
 * Synthetic wrapper tags codex injects into the first user turn (and into
 * developer-role turns). Observed across 177/177 production codex transcripts:
 *   - user role:      <environment_context>, # AGENTS.md instructions for …
 *   - developer role: <permissions>, <collaboration_mode>, <skills_instructions>,
 *                     <plugins_instructions>, <apps_instructions>, <app-context>
 *
 * The codex parser already drops developer-role messages, but we include those
 * tags defensively — codex versions have migrated wrappers between roles before.
 */
// Tag names only — the regex below captures the first tag-name token, so a
// wrapper like `<permissions instructions>` (space-separated, codex emits this
// verbatim) is matched by the "permissions" entry alone.
const CODEX_SYNTHETIC_WRAPPER_TAGS = new Set([
  "environment_context",
  "user_instructions",
  "turn_aborted",
  "permissions",
  "collaboration_mode",
  "skills_instructions",
  "plugins_instructions",
  "apps_instructions",
  "app-context",
])

/**
 * Identify a codex content item that is entirely a synthetic wrapper injected
 * by the runtime (AGENTS.md dump, environment context, etc.). Matching is
 * anchored at the start of the text so legitimate user prose that happens to
 * mention one of these tags is not filtered.
 *
 * Positional caveat: a block can match this check and still be user-authored
 * (e.g. the user pastes "<environment_context>..." later in the conversation
 * to ask about it). Callers MUST scope invocation to the codex preamble — only
 * call this before the first real user message has been emitted. See the
 * `hasEmittedUserMessage` gates in the codex and unified transcript parsers.
 */
export function isSyntheticInputText(text: string): boolean {
  const trimmed = text.trim()
  if (!trimmed) return false
  if (trimmed.startsWith("# AGENTS.md instructions for ") && trimmed.includes("<INSTRUCTIONS>")) {
    return true
  }
  // Greedy capture of the tag-name token. Hyphens are part of tag names
  // (e.g. `app-context`); a lazy quantifier with `\b` would capture only up
  // to the hyphen. Anything after the name (space, `>`, attributes) is
  // ignored — the set lookup covers the observed forms.
  const match = trimmed.match(/^<([a-z_][a-z0-9_\-]*)/i)
  if (!match) return false
  return CODEX_SYNTHETIC_WRAPPER_TAGS.has(match[1].toLowerCase())
}

