// Strips transcript JSONL to only the fields needed by transcript parsers.
// Reduces size by ~60-80% for efficient DB storage.
//
// The parsers read:
// - type, timestamp, requestId, uuid, message.id, message.content, toolUseResult
// We drop: progress, file-history-snapshot, queue-operation, system entries
// We strip: thinking blocks, tool_use caller field, unnecessary assistant fields

import type { TranscriptParser } from "./transcript-parsers/types"

// Entry types that carry no parser-relevant data
const DROPPED_TYPES = new Set(["progress", "file-history-snapshot", "queue-operation", "system"])

/**
 * Strip a transcript to only the fields the parser needs.
 *
 * When a parser is provided and has a strip() method, delegates to it.
 * Otherwise applies shared JSONL line-by-line stripping (the default).
 */
export function stripTranscript(content: string, parser?: TranscriptParser): string {
  if (parser?.strip) {
    return parser.strip(content)
  }

  const lines = content.split("\n")
  const result: string[] = []

  for (const line of lines) {
    const trimmed = line.trim()
    if (!trimmed) continue

    let parsed: Record<string, unknown>
    try {
      parsed = JSON.parse(trimmed)
    } catch {
      // Skip malformed lines
      continue
    }

    const entryType = parsed.type as string | undefined

    // Drop entry types that parsers ignore
    if (entryType && DROPPED_TYPES.has(entryType)) {
      continue
    }

    const stripped = stripEntry(parsed, entryType)
    if (stripped) {
      result.push(JSON.stringify(stripped))
    }
  }

  return result.join("\n")
}

function stripEntry(
  parsed: Record<string, unknown>,
  entryType: string | undefined,
): Record<string, unknown> | null {
  if (entryType === "assistant") {
    return stripAssistantEntry(parsed)
  }

  if (entryType === "user") {
    return stripUserEntry(parsed)
  }

  // Unknown entry type — pass through with just type/timestamp/message to be safe
  // This handles future entry types or non-Claude agents (e.g. Cursor uses "role" instead of "type")
  const out: Record<string, unknown> = {}
  if (parsed.type !== undefined) out.type = parsed.type
  if (parsed.role !== undefined) out.role = parsed.role
  if (parsed.timestamp !== undefined) out.timestamp = parsed.timestamp
  if (parsed.message !== undefined) out.message = parsed.message
  if (parsed.uuid !== undefined) out.uuid = parsed.uuid
  if (parsed.requestId !== undefined) out.requestId = parsed.requestId
  return out
}

function stripAssistantEntry(parsed: Record<string, unknown>): Record<string, unknown> {
  const out: Record<string, unknown> = {
    type: "assistant",
  }

  if (parsed.timestamp !== undefined) out.timestamp = parsed.timestamp
  if (parsed.requestId !== undefined) out.requestId = parsed.requestId

  const message = parsed.message as Record<string, unknown> | undefined
  if (message) {
    const strippedMessage: Record<string, unknown> = {}
    if (message.id !== undefined) strippedMessage.id = message.id

    // Strip content: remove thinking blocks, strip caller from tool_use
    if (message.content !== undefined) {
      strippedMessage.content = stripAssistantContent(message.content)
    }

    out.message = strippedMessage
  }

  return out
}

function stripAssistantContent(content: unknown): unknown {
  // String content — keep as-is
  if (typeof content === "string") return content

  // Array of content blocks
  if (Array.isArray(content)) {
    const stripped: unknown[] = []
    for (const block of content) {
      if (typeof block !== "object" || block === null) {
        stripped.push(block)
        continue
      }

      const b = block as Record<string, unknown>

      // Drop thinking blocks
      if (b.type === "thinking" || b.type === "redacted_thinking") {
        continue
      }

      // Strip tool_use: keep id, name, input — drop caller
      if (b.type === "tool_use") {
        const toolUse: Record<string, unknown> = {
          type: "tool_use",
        }
        if (b.id !== undefined) toolUse.id = b.id
        if (b.name !== undefined) toolUse.name = b.name
        if (b.input !== undefined) toolUse.input = b.input
        stripped.push(toolUse)
        continue
      }

      // Other block types (text, image) — keep as-is
      stripped.push(block)
    }
    return stripped
  }

  return content
}

function stripUserEntry(parsed: Record<string, unknown>): Record<string, unknown> {
  const out: Record<string, unknown> = {
    type: "user",
  }

  if (parsed.timestamp !== undefined) out.timestamp = parsed.timestamp
  if (parsed.uuid !== undefined) out.uuid = parsed.uuid

  // Keep toolUseResult but minimize it
  if (parsed.toolUseResult !== undefined) {
    out.toolUseResult = stripToolUseResult(parsed.toolUseResult)
  }

  const message = parsed.message as Record<string, unknown> | undefined
  if (message) {
    const strippedMessage: Record<string, unknown> = {}

    if (message.content !== undefined) {
      strippedMessage.content = stripUserContent(message.content)
    }

    out.message = strippedMessage
  }

  return out
}

function stripUserContent(content: unknown): unknown {
  // String content — keep as-is
  if (typeof content === "string") return content

  // Array of content blocks
  if (Array.isArray(content)) {
    const stripped: unknown[] = []
    for (const block of content) {
      if (typeof block !== "object" || block === null) {
        stripped.push(block)
        continue
      }

      const b = block as Record<string, unknown>

      // tool_result: keep type and tool_use_id only (content is in toolUseResult)
      if (b.type === "tool_result") {
        const toolResult: Record<string, unknown> = {
          type: "tool_result",
        }
        if (b.tool_use_id !== undefined) toolResult.tool_use_id = b.tool_use_id
        stripped.push(toolResult)
        continue
      }

      // Other block types (text, image) — keep as-is
      stripped.push(block)
    }
    return stripped
  }

  return content
}

function stripToolUseResult(result: unknown): unknown {
  if (typeof result !== "object" || result === null) return result

  const r = result as Record<string, unknown>
  const out: Record<string, unknown> = {}

  if (r.type !== undefined) out.type = r.type
  if (r.file !== undefined) out.file = r.file
  if (r.error !== undefined) out.error = r.error
  if (r.answers !== undefined) out.answers = r.answers

  return out
}

package claudecode

import (
	"bufio"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"os/exec"

	"github.com/entireio/cli/cmd/entire/cli/review"
	reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
)

// envelopeTypeAssistant is the stream-json envelope type for assistant
// messages (per-content-block events). Shared with transcript.go's usage.
const envelopeTypeAssistant = "assistant"

// NewReviewer returns the AgentReviewer for claude-code.
//
// Argv shape: claude -p <prompt> --output-format stream-json --verbose.
// The prompt is passed as a command-line argument; stdin is unused.
// Stdout is newline-delimited JSON envelopes (one event per line), which the
// parser decodes into the review Event stream. This format gives the parser
// per-message granularity (each assistant content block surfaces as it is
// produced) instead of buffering until end-of-run like plain-text -p mode.
func NewReviewer() *reviewtypes.ReviewerTemplate {
	return &reviewtypes.ReviewerTemplate{
		AgentName: "claude-code",
		BuildCmd:  buildReviewCmd,
		Parser:    parseClaudeOutput,
	}
}

// buildReviewCmd builds the exec.Cmd for a claude review run.
// Exposed at package level for test inspection of argv and env.
func buildReviewCmd(ctx context.Context, cfg reviewtypes.RunConfig) *exec.Cmd {
	prompt := review.ComposeReviewPrompt(cfg)
	cmd := exec.CommandContext(ctx, "claude", "-p", prompt, "--output-format", "stream-json", "--verbose")
	cmd.Env = review.AppendReviewEnv(os.Environ(), "claude-code", cfg, prompt)
	return cmd
}

// parseClaudeOutput converts claude's --output-format stream-json --verbose
// stdout into a stream of Events. Each stdout line is one JSON envelope:
//   - {"type":"system",...}      session metadata / hooks; swallowed
//   - {"type":"assistant",...}   per content block: text → AssistantText,
//     tool_use → ToolCall, thinking → swallowed
//   - {"type":"user",...}        tool_result echoes; swallowed
//   - {"type":"result",...}      final summary; emits Tokens then Finished
//
// Emits Started first, Finished{Success:...} last (success follows result.is_error).
// On a scanner error (torn stream), emits RunError then Finished{Success:false}.
//
// Tokens are emitted only at the terminal `result` envelope, not
// incrementally — claude's per-assistant `usage` fields aren't cumulative
// and summing them across messages would double-count.
//
// Package-private; called directly from this package's tests so they can
// drive raw stdout fixtures through the parser without going through the
// ReviewerTemplate.Start spawn path.
func parseClaudeOutput(r io.Reader) <-chan reviewtypes.Event {
	return parseClaudeOutputBuf(r, claudeReviewMaxScannerBuf)
}

// claudeReviewMaxScannerBuf is the production bufio.Scanner cap for the Claude
// review parser. 64MB matches codex (which can pack large command stdout into
// aggregated_output); Claude's stream-json envelopes are small in practice but
// we share the cap so both parsers tolerate the same worst case. One buffer
// per active review run; memory cost is modest.
const claudeReviewMaxScannerBuf = 64 * 1024 * 1024

// parseClaudeOutputBuf is the parameterized variant of parseClaudeOutput, used
// by tests to shrink the scanner cap so the "token too long" branch can be
// exercised without writing 64MB of fixture data.
func parseClaudeOutputBuf(r io.Reader, maxBuf int) <-chan reviewtypes.Event {
	out := make(chan reviewtypes.Event, 32)
	go func() {
		defer close(out)
		out <- reviewtypes.Started{}
		scanner := bufio.NewScanner(r)
		scanner.Buffer(make([]byte, min(1024*1024, maxBuf)), maxBuf)
		var sawResult bool
		var resultErr bool
		var resultUsage messageUsage
		for scanner.Scan() {
			line := scanner.Bytes()
			if len(line) == 0 {
				continue
			}
			var env claudeEnvelope
			if err := json.Unmarshal(line, &env); err != nil {
				out <- reviewtypes.RunError{Err: fmt.Errorf("claude stream-json: %w", err)}
				continue
			}
			switch env.Type {
			case envelopeTypeAssistant:
				for _, block := range env.Message.Content {
					switch block.Type {
					case "text":
						if block.Text != "" {
							out <- reviewtypes.AssistantText{Text: block.Text}
						}
					case "tool_use":
						// block.Input is a json.RawMessage; passing it through as a
						// string preserves the agent-defined shape without a
						// re-marshal round trip. Empty input becomes "" so consumers
						// see a falsy Args.
						out <- reviewtypes.ToolCall{Name: block.Name, Args: string(block.Input)}
					}
				}
			case "result":
				sawResult = true
				resultErr = env.IsError
				resultUsage = env.Usage
			}
		}
		if err := scanner.Err(); err != nil {
			out <- reviewtypes.RunError{Err: fmt.Errorf("read stdout: %w", err)}
			out <- reviewtypes.Finished{Success: false}
			return
		}
		if sawResult {
			in := resultUsage.InputTokens + resultUsage.CacheReadInputTokens + resultUsage.CacheCreationInputTokens
			out <- reviewtypes.Tokens{In: in, Out: resultUsage.OutputTokens}
			out <- reviewtypes.Finished{Success: !resultErr}
			return
		}
		out <- reviewtypes.Finished{Success: false}
	}()
	return out
}

type claudeEnvelope struct {
	Type    string        `json:"type"`
	Message claudeMessage `json:"message"`
	IsError bool          `json:"is_error"`
	// Usage reuses the package-local messageUsage type (declared in types.go)
	// rather than a duplicate ad-hoc struct, so the two consumers of the
	// Claude API usage shape (transcript parsing + stream-json review parser)
	// can't drift apart.
	Usage messageUsage `json:"usage"`
}

type claudeMessage struct {
	Content []claudeBlock `json:"content"`
}

type claudeBlock struct {
	Type  string          `json:"type"`
	Text  string          `json:"text"`
	Name  string          `json:"name"`
	Input json.RawMessage `json:"input"`
}

package codex

import (
	"bufio"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"log/slog"
	"os"
	"os/exec"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/review"
	reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
)

// NewReviewer returns the AgentReviewer for codex.
//
// Argv shape: codex exec --skip-git-repo-check --json -.
// Prompt is piped via stdin (the trailing "-" tells codex to read from stdin).
// Stdout is newline-delimited JSON envelopes (one event per line); no chrome
// filter needed — each line is parsed directly into an Event.
func NewReviewer() *reviewtypes.ReviewerTemplate {
	return &reviewtypes.ReviewerTemplate{
		AgentName: "codex",
		BuildCmd:  buildCodexReviewCmd,
		Parser:    parseCodexOutput,
	}
}

// buildCodexReviewCmd builds the exec.Cmd for a codex review run.
// Exposed at package level for test inspection of argv, stdin, and env.
func buildCodexReviewCmd(ctx context.Context, cfg reviewtypes.RunConfig) *exec.Cmd {
	promptCfg := cfg
	promptCfg.Skills = expandCodexBuiltinReview(cfg.Skills)
	args := []string{codexExecCommand, "--skip-git-repo-check", "--json", "-"}
	prompt := review.ComposeReviewPrompt(promptCfg)
	cmd := exec.CommandContext(ctx, "codex", args...)
	cmd.Stdin = strings.NewReader(prompt)
	cmd.Env = review.AppendReviewEnv(os.Environ(), "codex", cfg, prompt)
	return cmd
}

// Codex's native `exec review --base <branch>` rejects an additional prompt,
// so expand `/review` into text and run normal `codex exec -`. That preserves
// Entire's scoped base clause, per-run instructions, and checkpoint context.
const codexBuiltinReviewPrompt = "Review the current branch changes and report actionable findings. " +
	"Prioritize correctness, regressions, security, and missing test coverage. Do not make code changes."

const codexExecCommand = "exec"

func expandCodexBuiltinReview(skills []string) []string {
	out := make([]string, 0, len(skills))
	for _, skill := range skills {
		if skill == "/review" {
			out = append(out, codexBuiltinReviewPrompt)
			continue
		}
		out = append(out, skill)
	}
	return out
}

// parseCodexOutput converts codex's `exec --json` stdout into a stream of
// Events. Each stdout line is one JSON envelope (top-level "type" field).
//
// Envelope types this parser handles:
//   - thread.started        session id; swallowed
//   - turn.started          marker; swallowed
//   - item.started          tool invocation begins → emits ToolCall when
//     item.type == "command_execution"
//   - item.completed        tool invocation ends OR an agent_message;
//     agent_message → AssistantText
//     command_execution → swallowed (start already announced)
//   - turn.completed        terminal usage block → Tokens, then Finished
//
// On a scanner error or a missing turn.completed envelope, emits RunError
// (scanner) or Finished{Success: false} (missing turn) accordingly.
//
// Tokens are emitted only at the terminal `turn.completed` envelope, not
// incrementally — codex's usage fields land once at end-of-turn.
//
// Package-private; called directly from this package's tests so they can
// drive raw stdout fixtures through the parser without going through the
// ReviewerTemplate.Start spawn path.
func parseCodexOutput(r io.Reader) <-chan reviewtypes.Event {
	return parseCodexOutputBuf(r, codexReviewMaxScannerBuf)
}

// codexReviewMaxScannerBuf is the production bufio.Scanner cap for the codex
// review parser. Codex packs the entire stdout of `command_execution` tools
// into the aggregated_output field on item.completed envelopes inline, so a
// chatty grep/cat/find over a large repo can put many MB into one envelope.
// 16MB was too tight; 64MB is generous without imposing real memory cost
// (one buffer per active review run).
const codexReviewMaxScannerBuf = 64 * 1024 * 1024

// parseCodexOutputBuf is the parameterized variant of parseCodexOutput, used
// by tests to shrink the scanner cap so the "token too long" branch can be
// exercised without writing 64MB of fixture data.
func parseCodexOutputBuf(r io.Reader, maxBuf int) <-chan reviewtypes.Event {
	out := make(chan reviewtypes.Event, 32)
	go func() {
		defer close(out)
		out <- reviewtypes.Started{}
		scanner := bufio.NewScanner(r)
		scanner.Buffer(make([]byte, min(1024*1024, maxBuf)), maxBuf)
		var seenTurnComplete bool
		var turnUsage codexUsage
		for scanner.Scan() {
			line := scanner.Bytes()
			if len(line) == 0 {
				continue
			}
			var env codexEnvelope
			if err := json.Unmarshal(line, &env); err != nil {
				out <- reviewtypes.RunError{Err: fmt.Errorf("codex --json: %w", err)}
				continue
			}
			// Add cases here when codex's envelope or item types grow; the
			// default arm logs unknown types at Debug so drift can be
			// triaged via ENTIRE_LOG_LEVEL=debug.
			switch env.Type {
			case "thread.started", "turn.started":
				// Session/turn markers — no event emitted.
			case "item.started":
				if env.Item.Type == "command_execution" {
					out <- reviewtypes.ToolCall{Name: "exec", Args: env.Item.Command}
				}
			case "item.completed":
				if env.Item.Type == "agent_message" && env.Item.Text != "" {
					out <- reviewtypes.AssistantText{Text: env.Item.Text}
				}
				// command_execution completion is intentionally swallowed —
				// item.started already announced it. aggregated_output is the
				// tool's stdout, not the model's narrative.
			case "turn.completed":
				seenTurnComplete = true
				turnUsage = env.Usage
			default:
				logging.Debug(context.Background(), "codex parser: unknown envelope type",
					slog.String("type", env.Type))
			}
		}
		if err := scanner.Err(); err != nil {
			out <- reviewtypes.RunError{Err: fmt.Errorf("read stdout: %w", err)}
			out <- reviewtypes.Finished{Success: false}
			return
		}
		if seenTurnComplete {
			// codex reports cached_input_tokens as a subset of input_tokens
			// and reasoning_output_tokens as a subset of output_tokens
			// (matching OpenAI's chat-completions usage shape), so do NOT
			// sum the subset fields — that would double-count.
			out <- reviewtypes.Tokens{
				In:  turnUsage.InputTokens,
				Out: turnUsage.OutputTokens,
			}
			// Success is hard-coded true here because codex's `turn.completed`
			// envelope has no turn-level error field in 0.130.0. If a future
			// codex version adds one (e.g., an `error` or `is_error` field on
			// the envelope), capture it into a local during the switch case and
			// thread it through here as `!turnErr` — mirroring claude's
			// `!resultErr` pattern.
			out <- reviewtypes.Finished{Success: true}
			return
		}
		out <- reviewtypes.Finished{Success: false}
	}()
	return out
}

type codexEnvelope struct {
	Type  string     `json:"type"`
	Item  codexItem  `json:"item"`
	Usage codexUsage `json:"usage"`
}

type codexItem struct {
	Type    string `json:"type"`
	Command string `json:"command"`
	Text    string `json:"text"`
}

type codexUsage struct {
	InputTokens           int `json:"input_tokens"`
	CachedInputTokens     int `json:"cached_input_tokens"`
	OutputTokens          int `json:"output_tokens"`
	ReasoningOutputTokens int `json:"reasoning_output_tokens"`
}

package geminicli

import (
	"bufio"
	"context"
	"fmt"
	"io"
	"os"
	"os/exec"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/review"
	reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
)

// NewReviewer returns the AgentReviewer for gemini.
//
// Argv shape: gemini -p " " (space placeholder to trigger headless mode).
// Prompt is piped via stdin; per gemini --help the -p flag appends to stdin
// content, so passing a single space lets stdin carry the actual prompt.
// Stdout in this mode is the assistant text directly — parsed line-by-line.
func NewReviewer() *reviewtypes.ReviewerTemplate {
	return &reviewtypes.ReviewerTemplate{
		AgentName: string(agent.AgentNameGemini),
		BuildCmd:  buildGeminiReviewCmd,
		Parser:    parseGeminiOutput,
	}
}

// buildGeminiReviewCmd builds the exec.Cmd for a gemini review run.
// Exposed at package level for test inspection of argv, stdin, and env.
func buildGeminiReviewCmd(ctx context.Context, cfg reviewtypes.RunConfig) *exec.Cmd {
	prompt := review.ComposeReviewPrompt(cfg)
	// Per the existing GenerateText implementation: pass "-p " " " as the
	// argv placeholder to trigger headless (non-interactive) mode, and pipe
	// the actual prompt via stdin to avoid argv size limits.
	cmd := exec.CommandContext(ctx, "gemini", "-p", " ")
	cmd.Stdin = strings.NewReader(prompt)
	// Agent name must equal string(ag.Name()) — adoptReviewEnv compares
	// ENTIRE_REVIEW_AGENT against it; any drift silently skips adoption.
	cmd.Env = review.AppendReviewEnv(os.Environ(), string(agent.AgentNameGemini), cfg, prompt)
	return cmd
}

// parseGeminiOutput converts gemini's -p mode stdout into a stream of Events.
// Gemini emits clean assistant output with no chrome — the parser emits Started
// once, then one AssistantText per non-empty line, then Finished{Success: true}
// on clean EOF or RunError + Finished{Success: false} on a torn stream.
//
// Exposed for golden-file contract testing.
func parseGeminiOutput(r io.Reader) <-chan reviewtypes.Event {
	out := make(chan reviewtypes.Event, 32)
	go func() {
		defer close(out)
		out <- reviewtypes.Started{}
		scanner := bufio.NewScanner(r)
		scanner.Buffer(make([]byte, 1024*1024), 16*1024*1024)
		for scanner.Scan() {
			line := scanner.Text()
			if line == "" {
				continue
			}
			out <- reviewtypes.AssistantText{Text: line}
		}
		if err := scanner.Err(); err != nil {
			out <- reviewtypes.RunError{Err: fmt.Errorf("read stdout: %w", err)}
			out <- reviewtypes.Finished{Success: false}
			return
		}
		out <- reviewtypes.Finished{Success: true}
	}()
	return out
}

// Package review — see env.go for package-level rationale.
//
// prompt.go implements the shared prompt composer used by all per-agent
// reviewers. The scope clause pins agents to "commits unique to this branch
// vs the mainline base ref, plus uncommitted working-tree changes" —
// preventing the divergent-default problem where codex defaulted to
// origin/main...HEAD and claude defaulted to working-tree-only on the same
// invocation (regression class from #1018 commit b9ed9c074; enforced
// structurally here).
package review

import (
	"strings"

	reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
)

// ComposeReviewPrompt assembles the prompt sent to the agent. It joins
// the configured skill invocations, the always-prompt, the per-run
// prompt, and a scope clause that pins the agent to commits unique to
// the current branch vs cfg.ScopeBaseRef plus any uncommitted changes.
//
// Empty sections are skipped (no triple-newline gaps). The scope clause
// is only added when cfg.ScopeBaseRef is non-empty.
func ComposeReviewPrompt(cfg reviewtypes.RunConfig) string {
	if cfg.PromptOverride != "" {
		return cfg.PromptOverride
	}

	var sections []string

	// Skills: one per line, joined as a single section.
	if len(cfg.Skills) > 0 {
		sections = append(sections, strings.Join(cfg.Skills, "\n"))
	}

	// AlwaysPrompt and PerRunPrompt: each is its own section if non-empty after trim.
	if trimmed := strings.TrimRight(cfg.AlwaysPrompt, "\n\r "); trimmed != "" {
		sections = append(sections, trimmed)
	}
	if trimmed := strings.TrimRight(cfg.PerRunPrompt, "\n\r "); trimmed != "" {
		sections = append(sections, trimmed)
	}

	// Scope clause: only when a base ref was detected. Includes uncommitted
	// working-tree changes alongside the committed branch diff so iterative
	// edits-in-progress are reviewed too — without this, agents correctly
	// follow "commits-only" wording and silently skip uncommitted work,
	// which is the most common case when a developer is mid-feature.
	if cfg.ScopeBaseRef != "" {
		sections = append(sections,
			"Scope: review the commits unique to this branch vs "+cfg.ScopeBaseRef+
				", plus any uncommitted changes in the working tree. Ignore code outside this scope.")
	}
	if trimmed := strings.TrimRight(cfg.CheckpointContext, "\n\r "); trimmed != "" {
		sections = append(sections, trimmed)
	}

	return strings.Join(sections, "\n\n")
}

// Package types defines the per-agent abstraction interfaces for `entire review`.
//
// AgentReviewer is the contract every supported agent (claude-code, codex,
// gemini, future additions) implements in its own package. The orchestrator
// in cmd/entire/cli/review/run.go consumes this interface, never importing
// concrete agent packages — that's how new agents land as additive files
// without touching shared code.
//
// Events flow as a stream: implementations spawn the agent process, parse
// stdout into a sequence of typed Events (Started, AssistantText, ToolCall,
// Tokens, Finished, RunError), and surface them via Process.Events. Per-agent
// quirks (codex's JSONL envelope shape, gemini's stdin requirement, claude's
// argv shape) are entirely encapsulated inside each agent's adapter — shared
// code only sees the cleaned event stream.
//
// Living in a subpackage (not the review root package) avoids import cycles:
// per-agent reviewers and the orchestrator both depend on these types
// without depending on each other.
package types

import "context"

// AgentReviewer drives a single agent's review run.
type AgentReviewer interface {
	// Name returns the agent's registry key (e.g., "claude-code", "codex",
	// "gemini"). Stable identifier; do not change after release without
	// updating settings migration.
	Name() string

	// Start spawns the agent with the given run configuration. The returned
	// Process exposes streaming events via Events() and a Wait() that returns
	// when the process exits.
	//
	// Implementations MUST set the ENTIRE_REVIEW_* env vars on the spawned
	// child process (see cmd/entire/cli/review/env.go) so the agent's
	// lifecycle hooks adopt the session as a review session.
	//
	// Errors from Start indicate failure to construct or launch the process
	// (e.g., binary not on PATH at exec.Cmd.Start time, invalid argv). Once
	// Start returns nil, errors during the run flow through Process.Events
	// (as RunError) and Process.Wait.
	Start(ctx context.Context, run RunConfig) (Process, error)
}

// Process represents a running agent review.
type Process interface {
	// Events returns a channel that emits structured events as the agent
	// produces output. The channel is closed when the process exits — cleanly,
	// with error, or via context cancellation. Consumers should range over it.
	Events() <-chan Event

	// Wait blocks until the process exits and returns:
	//   - nil on clean exit (exit code 0)
	//   - ctx.Err() on cancellation
	//   - an error wrapping *exec.ExitError on non-zero exit
	//   - other error types for I/O or pipe failures
	//
	// Wait must be called exactly once per Process. It is safe to call Wait
	// after the Events channel has closed. Consumers must drain Events until
	// close before calling Wait; otherwise an implementation that forwards
	// parsed events from another goroutine may block while sending.
	Wait() error
}

// RunConfig is the immutable per-run configuration passed to AgentReviewer.Start.
//
// All fields are optional from a marshalling standpoint (zero value is valid),
// but Skills is typically non-empty in practice — it carries the skill
// invocations (e.g., "/pr-review-toolkit:review-pr") the configured agent
// should run.
type RunConfig struct {
	// PromptOverride, when non-empty, is the exact prompt sent to the agent.
	// It preserves settings.ReviewConfig.Prompt's existing verbatim-override
	// contract: configured skills are still recorded as structured metadata,
	// but they are not prepended to the prompt text.
	PromptOverride string

	// Skills are skill invocation strings passed to the agent verbatim.
	Skills []string

	// AlwaysPrompt is the per-agent always-prompt configured in settings.
	// Concatenated with Skills + PerRunPrompt + a scope clause to form the
	// composed agent prompt.
	AlwaysPrompt string

	// PerRunPrompt is optional textarea input from a single invocation.
	PerRunPrompt string

	// ScopeBaseRef is the git ref the review is scoped against (mainline by
	// default — origin/HEAD → origin/main → origin/master → main → master —
	// or whatever `--base` overrides it to). Used to compose the scope clause
	// and as the base for `git diff` operations the agent may perform.
	ScopeBaseRef string

	// CheckpointContext is best-effort context derived from checkpoints in the
	// branch review scope. It is appended to generated prompts so every agent
	// can use checkpoint IDs, file summaries, and transcript lookup commands
	// while reviewing. PromptOverride remains verbatim and does not receive
	// this context.
	CheckpointContext string

	// StartingSHA is HEAD at invocation time, propagated to the lifecycle
	// hook via ENTIRE_REVIEW_STARTING_SHA so checkpoint metadata records
	// the commit that was reviewed.
	StartingSHA string

	// EnrichSummary optionally updates the completed run summary before sinks
	// receive RunFinished. It is used for post-process data such as token
	// totals that are only available after agent lifecycle hooks flush state.
	//
	// Timing: called on the orchestrator goroutine after every per-agent
	// goroutine has exited, immediately before Sink.RunFinished is fanned
	// out. The full RunSummary is consumed; any field the callback
	// returns reaches the sinks.
	//
	// Contract: nil is valid (no enrichment). The callback must not block on
	// a sink (deadlock), must not panic (no orchestrator-side recovery), and
	// should honor ctx for cancellation when doing I/O.
	EnrichSummary func(context.Context, RunSummary) RunSummary

	// EnrichAgentRun optionally updates a single agent run after that agent
	// exits, before the overall multi-agent run has necessarily completed.
	//
	// Timing: called on the per-agent forwarding goroutine in RunMulti,
	// after proc.Wait() returns and after any synthetic RunError is queued.
	// Only the returned Tokens field is consumed (emitted as a synthetic
	// Tokens event so sinks see live token totals before sibling agents
	// finish); other field changes are discarded. Returning Tokens{In:0,
	// Out:0} suppresses emission entirely.
	//
	// Contract: nil is valid (no enrichment). The callback must be
	// goroutine-safe across N agents and must not block on a sink. A panic
	// is recovered; no synthetic Tokens event is emitted on panic.
	EnrichAgentRun func(context.Context, AgentRun) AgentRun
}

// Event is the sealed sum type emitted by Process.Events. The unexported
// isEvent method prevents external packages from adding event variants;
// adding a new event requires updating this file (and every consumer's
// type switch — that's intentional, since a new event variant is a contract
// change).
type Event interface{ isEvent() }

// Started signals the agent has begun the review. Adapters typically emit
// this once at the top of the event stream.
type Started struct{}

func (Started) isEvent() {}

// AssistantText is narrative output from the agent (the actual review
// response, not tool-call chrome or session metadata).
type AssistantText struct {
	Text string
}

func (AssistantText) isEvent() {}

// ToolCall reports a tool invocation by the agent. Args is an opaque
// adapter-defined string — typically JSON for agents that emit structured
// tool input (e.g., claude-code), or a single-line summary for those that
// don't (e.g., codex). Shared consumers should treat Args as display-only
// and not parse it; structured tool data is intentionally not part of this
// contract.
type ToolCall struct {
	Name string
	Args string
}

func (ToolCall) isEvent() {}

// Tokens reports cumulative token counts (running totals, not deltas).
// Adapters may emit multiple Tokens events during a run; each emission
// supersedes the prior, so consumers should overwrite (not sum) on receipt.
// Adapters that only receive aggregate shutdown totals should emit at most one
// final Tokens event rather than inventing deltas.
type Tokens struct {
	In  int
	Out int
}

func (Tokens) isEvent() {}

// Finished signals the agent has produced its final output and the event
// stream is about to end. Success indicates the agent self-reported a
// clean task completion. Success=false means the agent finished its event
// stream but signaled it did not complete the review task — distinct from
// process exit failure (which surfaces via Process.Wait, not as an event).
//
// Adapters typically emit this once at the bottom of the event stream,
// before the channel closes.
type Finished struct {
	Success bool
}

func (Finished) isEvent() {}

// RunError reports a non-fatal error during the run (e.g., hook failure,
// transient stream parse error). Fatal errors that stop the agent surface
// via Process.Wait, not as events.
type RunError struct {
	Err error
}

func (RunError) isEvent() {}

// Package review contains the env-var contract between `entire review` (which
// spawns the agent process) and the lifecycle hook (which adopts the session).
// These names are stable API; renaming any constant is a breaking change.
//
// Design rationale: each spawned agent inherits its own copy of the process
// environment, so multi-tenant correctness (multiple worktrees, multi-agent
// runs) holds by construction — one agent's env vars cannot bleed into
// another agent's session. The lifecycle UserPromptSubmit hook reads these
// env vars to tag the in-flight session as a review session (Kind =
// "agent_review") and records which skills were run.
package review

import (
	"encoding/json"
	"fmt"
