	if ev.Prompt != "do thing" {
		t.Errorf("Prompt = %q", ev.Prompt)
	}
	if ev.SessionRef != "/tmp/2026-05-09T12-00-00-000Z_abc-123.jsonl" {
		t.Errorf("SessionRef = %q", ev.SessionRef)
	}
}

